using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Akiba: an Akihabara night, everything wearing photographs (generated by Tools/gen_akiba_photos.py,
// the Mallbat look) on low-poly shapes, drawn a little rough in the PlayStation style. A long main street
// packed both sides with neon-covered buildings, shop stalls and machines on the pavements, slow traffic
// both ways (long buses you can get on, ramp trucks you can ride up), a median strip of junk to skate
// down the middle, side streets strung with power lines, an elevated railway with Akihabara station and
// a train, flying cars (some going round on their own, some you fly yourself), skyscrapers up to 210 m
// with rails spiralling up them, and power lines between pylons on top of the tallest.
//
// Rails go everywhere, Jet Set Radio style, and the curvy ones are easy: they grab you from a couple of
// metres away and rush you along until you jump off.
//
// The route the level's built round, from the start at the south end: kick off the ramp on the east
// pavement onto the curving rail, it rushes you up onto a balcony, ride the sign ramp up to the roof, hop
// onto the flying car that pulls up alongside, ride it across the street and up the skyscraper's face
// until the pipe up its corner grabs you, and that takes you up into the power lines over the city.
public static partial class SkateWorldBuilder
{
    public const string AkibaPath = "Assets/Scenes/Akiba.unity";
    const string AkibaTex = "Assets/Akiba/Textures", AkibaMats = "Assets/Akiba/Materials", AkibaPhotos = "Assets/Akiba/Photos";

    const float AveLen = 480f, Road = 12f, Front = 20f;    // street runs along z; buildings' fronts at x = +-20
    static readonly float[] CrossZ = { -320f, -160f, 160f, 320f };
    const float CrossHalf = 8f, RailHalf = 14f, AkibaDeck = 12f;
    const float LaneIn = 5.5f, LaneOut = 9.5f, Median = 3.5f;   // traffic lanes either side, a skate strip down the middle
    const float CurvyCatch = 2.2f, CurvySpeed = 16f;           // the curvy rails: grab distance, and how fast they carry you

    static readonly Dictionary<string, PSXKit> akKits = new Dictionary<string, PSXKit>();
    static readonly Dictionary<string, Material> akMats = new Dictionary<string, Material>();
    static System.Random ark;
    static Transform akRoot, akCol;
    static readonly List<Vector3> akAnchors = new List<Vector3>();   // balcony and roof-edge points rails can join up
    static readonly List<Vector3> akNoStall = new List<Vector3>();   // pavement kept clear: side sign, z from, z to
    static readonly List<(Rect, float, float)> akLots = new List<(Rect, float, float)>();   // main-street buildings: lot, height, which way they face
    static readonly List<Vector2> akReserved = new List<Vector2>();  // stretches of the street (z from, z to) the bridges use

    static bool Reserved(float z, float margin = 4f)
    {
        foreach (var r in akReserved) if (z > r.x - margin && z < r.y + margin) return true;
        return false;
    }

    static float AR(float a, float b) { return a + (float)ark.NextDouble() * (b - a); }
    static int AI(int a, int b) { return ark.Next(a, b); }

    // ---- materials and textures ------------------------------------------------------------------

    static void ImportAkibaTextures()
    {
        AssetDatabase.Refresh();
        var files = new List<string>(Directory.GetFiles(AkibaTex, "*.png"));
        if (Directory.Exists(AkibaPhotos)) files.AddRange(Directory.GetFiles(AkibaPhotos, "*.png"));
        foreach (var path in files)
        {
            var imp = AssetImporter.GetAtPath(path.Replace('\\', '/')) as TextureImporter;
            if (imp == null) continue;
            var filter = path.Contains("Photos") ? FilterMode.Bilinear : FilterMode.Point;   // photos a touch softer
            if (imp.filterMode == filter && imp.textureCompression == TextureImporterCompression.Uncompressed && imp.maxTextureSize == 512) continue;
            imp.filterMode = filter;
            imp.wrapMode = TextureWrapMode.Repeat;
            imp.mipmapEnabled = true;
            imp.textureCompression = TextureImporterCompression.Uncompressed;
            imp.alphaIsTransparency = false;
            imp.maxTextureSize = 512;
            imp.SaveAndReimport();
        }
    }

    // the generated photo standing in for a texture name, if there is one
    static string Photo(string tex)
    {
        string p = tex;
        int n = 0;
        int us = tex.LastIndexOf('_');
        if (us > 0) int.TryParse(tex.Substring(us + 1), out n);
        switch (tex)
        {
            case "asphalt": p = "photo_asphalt"; break;
            case "pavement": p = "photo_pavement"; break;
            case "tactile": p = "photo_tactile"; break;
            case "concrete": p = "photo_concrete"; break;
            case "roof": p = "photo_roof"; break;
            case "shutter": p = "photo_shutter"; break;
            case "metal": p = "photo_metal"; break;
            case "posters": p = "photo_posters"; break;
            case "vending": p = "photo_vending"; break;
            case "gacha": p = "photo_gacha"; break;
            case "train_side": p = "photo_train"; break;
            default:
                if (tex.StartsWith("graffiti_")) p = "photo_graffiti_" + (n % 4);
                else if (tex.StartsWith("facade_")) p = "fac_akiba_" + (n % 6);
                else if (tex.StartsWith("shop_")) p = "shop_" + (n % 8);
                else if (tex.StartsWith("sign_v_")) p = "vsign_" + (n % 8);
                else if (tex.StartsWith("sign_h_")) p = "hsign_" + (n % 6);
                else if (tex.StartsWith("billboard_")) p = "ad_" + (n % 10);
                break;
        }
        return File.Exists(AkibaPhotos + "/" + p + ".png") ? p : null;
    }

    // style: "" lit by the moon, "e" full bright, "f" full bright and flickering, "s" full bright and scrolling
    static Material AkMat(string tex, string style)
    {
        string key = tex + "|" + style;
        Material m;
        if (akMats.TryGetValue(key, out m)) return m;
        Directory.CreateDirectory(AkibaMats);
        string path = AkibaMats + "/" + tex + (style == "" ? "" : "_" + style) + ".mat";
        m = AssetDatabase.LoadAssetAtPath<Material>(path);
        var sh = Shader.Find("3daigamesolo/PSX/Textured");
        if (m == null) { m = new Material(sh); AssetDatabase.CreateAsset(m, path); }
        m.shader = sh;
        string photo = Photo(tex);
        string file = photo != null ? AkibaPhotos + "/" + photo + ".png" : AkibaTex + "/" + tex + ".png";
        if (!File.Exists(file)) file = AkibaTex + "/white.png";
        m.SetTexture("_MainTex", AssetDatabase.LoadAssetAtPath<Texture2D>(file));
        m.SetFloat("_Emission", style == "" ? 0f : 1f);
        m.SetVector("_Scroll", style == "s" ? new Vector4(0.12f, 0f, 0f, 0f) : Vector4.zero);
        m.SetVector("_Flicker", style == "f" ? new Vector4(AR(0.3f, 1.4f), AR(0.6f, 0.92f), AR(0.25f, 0.5f), 0f) : new Vector4(0f, 1f, 1f, 0f));
        m.SetFloat("_Cutoff", 0f);
        EditorUtility.SetDirty(m);
        akMats[key] = m;
        return m;
    }

    static PSXKit AK(string tex, string style = "")
    {
        string key = tex + "|" + style;
        PSXKit k;
        if (!akKits.TryGetValue(key, out k)) { k = new PSXKit(); akKits[key] = k; AkMat(tex, style); }
        return k;
    }

    static void FlushAkiba(Transform parent)
    {
        foreach (var kv in akKits)
        {
            if (kv.Value.Empty) continue;
            var mesh = kv.Value.Build(kv.Key.Replace('|', '_'));
            SaveFeatureMesh(mesh);
            var go = new GameObject(kv.Key, typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(parent, false);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterial = akMats[kv.Key];
        }
        akKits.Clear();
    }

    static void AkBox(Vector3 c, Vector3 size, Quaternion? rot = null) { AddBox(akCol, "Solid", c, size, rot); }

    // for a panel facing n: the direction that's right to someone looking at it (so its picture reads the right way round)
    static Vector3 Rt(Vector3 n) { return Vector3.Cross(n, Vector3.up); }

    // a flat wall from p0 along `along` for `w` metres, from y0 to y1, facing `n`, tiled every tu x tv metres
    static void Wall(PSXKit k, Vector3 p0, Vector3 along, float w, float y0, float y1, Vector3 n, float tu, float tv, float v0 = 0f)
    {
        Vector3 a = new Vector3(p0.x, y0, p0.z), b = a + along * w;
        float va = (y0 - v0) / tv, vb = (y1 - v0) / tv;
        k.Quad(a, new Vector3(a.x, y1, a.z), new Vector3(b.x, y1, b.z), b,
               new Vector2(0f, va), new Vector2(0f, vb), new Vector2(w / tu, vb), new Vector2(w / tu, va), n);
    }

    // a wall facing n, `w` wide centred on `centre`, its picture left to right as you look at it
    static void FrontWall(PSXKit k, Vector3 centre, Vector3 n, float w, float y0, float y1, float tu, float tv, float v0 = 0f)
    {
        Vector3 along = Rt(n);
        Wall(k, new Vector3(centre.x, 0f, centre.z) - along * (w / 2f), along, w, y0, y1, n, tu, tv, v0);
    }

    // a kicker you can hit from either side: two back to back, lips meeting in the middle
    static void Hump(string name, Vector3 at, Vector3 dir, float radius, float degrees, float width, Color32 side)
    {
        float len = radius * Mathf.Sin(degrees * Mathf.Deg2Rad);
        Kicker(name, Matrix4x4.TRS(at, Quaternion.LookRotation(dir), Vector3.one), radius, degrees, width, side);
        Kicker(name, Matrix4x4.TRS(at + dir * len * 2f, Quaternion.LookRotation(-dir), Vector3.one), radius, degrees, width, side);
    }

    // a wedge ramp: from the ground at `at` rising along `dir` to `height` over `length`, `width` wide
    static void Wedge(string tex, Vector3 at, Vector3 dir, float length, float height, float width)
    {
        Vector3 top = at + dir * length + Vector3.up * height;
        Vector3 side = Rt(dir) * (width / 2f);
        var k = AK(tex);
        Vector2 u0 = new Vector2(0f, 0f), u1 = new Vector2(0f, length / 3f), u2 = new Vector2(width / 3f, length / 3f), u3 = new Vector2(width / 3f, 0f);
        Vector3 up = Vector3.Cross(dir, Rt(dir)).normalized; if (up.y < 0f) up = -up;
        k.Quad(at - side, top - side, top + side, at + side, u0, u1, u2, u3, Vector3.Cross(top - at, side));
        Vector3 back = at + dir * length;
        k.Quad(back - side, back - side + Vector3.up * height, back + side + Vector3.up * height, back + side, u0, u1, u2, u3, dir);
        foreach (var s in new[] { -1f, 1f })
            k.Quad(at + side * s, top + side * s, back + side * s, back + side * s, u0, u1, u2, u3, Rt(dir) * s);
        float slope = Mathf.Atan2(height, length) * Mathf.Rad2Deg, len = Mathf.Sqrt(height * height + length * length);
        Quaternion q = Quaternion.LookRotation(dir) * Quaternion.Euler(-slope, 0f, 0f);
        AkBox((at + top) / 2f + q * Vector3.down * 0.15f, new Vector3(width, 0.3f, len), q);
        AkBox(back + Vector3.up * height / 2f - dir * 0.15f, new Vector3(width, height, 0.3f), Quaternion.LookRotation(dir));
    }

    // ---- the level --------------------------------------------------------------------------------------

    // -executeMethod SkateWorldBuilder.AkibaFromCommandLine: just this level, its test runs and screenshots
    public static void AkibaFromCommandLine()
    {
        try { BuildAkiba(); SlideTests.RunAkiba(); AkibaShots(); }
        catch (System.Exception e) { Debug.LogException(e); EditorApplication.Exit(1); return; }
        EditorApplication.Exit(0);
    }

    public static void BuildAkiba()
    {
        Directory.CreateDirectory(Folder);
        featureCount = 0;
        featureFile = null;
        featureAsset = Folder + "/AkibaFeatures.asset";
        if (AssetDatabase.LoadMainAssetAtPath(featureAsset) != null) AssetDatabase.DeleteAsset(featureAsset);
        keepClear.Clear(); akKits.Clear(); akMats.Clear(); akAnchors.Clear(); akNoStall.Clear(); akLots.Clear(); akReserved.Clear();
        akNoStall.Add(new Vector3(1f, -440f, -400f));   // the route's kicker and rail on the east pavement
        foreach (var bz in BridgeZ)
        {
            // the footbridges' ramps run along the pavements: keep them clear
            akReserved.Add(new Vector2(bz - 24f, bz + 24f));
            akNoStall.Add(new Vector3(1f, bz - 24f, bz + 24f)); akNoStall.Add(new Vector3(-1f, bz - 24f, bz + 24f));
        }
        ark = new System.Random(19990629);
        floorAt = (x, z) => Mathf.Abs(x) > Road && Mathf.Abs(x) < Front + 0.5f ? Kerb : 0f;
        ImportAkibaTextures();

        // ramps, rails, ledges: plain shapes in the PSX shader (white texture, vertex colours), thin ink lines
        RampTop = new Color32(255, 200, 80, 255); RampSide = new Color32(170, 160, 190, 255); RampSide2 = new Color32(120, 220, 255, 255);
        Metal = new Color32(200, 200, 215, 255); RailCol = new Color32(255, 214, 40, 255);
        Concrete = new Color32(170, 168, 180, 255); ConcreteDark = new Color32(130, 126, 140, 255);
        toonMat = AkMat("white", "");
        outlineMat = Mat("AkibaOutline", "3daigamesolo/World/Outline");
        outlineMat.SetColor("_OutlineColor", new Color(0.05f, 0.02f, 0.09f));
        outlineMat.SetFloat("_OutlineWidth", 1f);
        outlineMat.SetColor("_Haze", new Color(0.16f, 0.08f, 0.24f)); outlineMat.SetColor("_HazeHigh", new Color(0.12f, 0.06f, 0.2f));
        outlineMat.SetFloat("_FogDensity", 0.003f); outlineMat.SetFloat("_FogHeight", 900f); outlineMat.SetFloat("_FogMax", 0.95f);
        farOutlineMat = outlineMat;
        var sky = Mat("AkibaSky", "3daigamesolo/World/Sky");
        sky.SetColor("_Zenith", new Color(0.05f, 0.03f, 0.14f)); sky.SetColor("_Horizon", new Color(0.55f, 0.24f, 0.5f));
        sky.SetColor("_Below", new Color(0.16f, 0.08f, 0.24f)); sky.SetColor("_Cloud", new Color(0.42f, 0.22f, 0.5f));
        sky.SetColor("_CloudShade", new Color(0.24f, 0.11f, 0.32f)); sky.SetFloat("_CloudCover", 0.45f);

        var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        RenderSettings.skybox = null;
        RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
        RenderSettings.ambientLight = Color.white;
        RenderSettings.fog = false;

        featureRoot = new GameObject("Skate features").transform;
        akRoot = new GameObject("Akiba").transform;
        akCol = new GameObject("Colliders").transform;
        akCol.SetParent(akRoot, false);

        AkStreets();
        AkRailway();
        AkBuildings();
        AkSideStreets();
        AkFlow();
        AkMedian();
        AkRoute();
        AkCurvyRails();
        AkTopLines();
        AkTraffic();
        AkHoverCars();
        AkWeird();
        FlushAkiba(akRoot);

        var skyGo = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        skyGo.name = "Sky";
        Object.DestroyImmediate(skyGo.GetComponent<Collider>());
        skyGo.transform.localScale = Vector3.one * 9000f;
        skyGo.GetComponent<Renderer>().sharedMaterial = sky;

        var start = new GameObject("Start");
        start.transform.SetPositionAndRotation(new Vector3(16f, Kerb + 0.2f, -462f), Quaternion.LookRotation(Vector3.forward));
        var camGO = new GameObject("Main Camera", typeof(Camera), typeof(AudioListener), typeof(SlideHUD), typeof(SkateAutoShot), typeof(LevelSwitcher), typeof(PSXCamera));
        camGO.tag = "MainCamera";
        var cam = camGO.GetComponent<Camera>();
        cam.nearClipPlane = 0.1f; cam.farClipPlane = 9000f;
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.16f, 0.08f, 0.24f);
        var psx = camGO.GetComponent<PSXCamera>();
        psx.fogColor = new Color(0.16f, 0.08f, 0.24f); psx.fogStart = 120f; psx.fogEnd = 900f;
        psx.height = 540; psx.snapGrid = new Vector2(640f, 360f); psx.affine = 0.15f;
        psx.ambient = new Color(0.55f, 0.5f, 0.66f); psx.moonStrength = 0.45f;
        psx.Apply();
        var player = BuildPlayer(start.transform, camGO.transform);
        player.fallLimit = -30f;
        camGO.GetComponent<SlideHUD>().player = player;
        camGO.GetComponent<SlideHUD>().levelName = "Akiba";
        camGO.transform.SetPositionAndRotation(new Vector3(16f, 2.5f, -467f), Quaternion.LookRotation(Vector3.forward));
        player.board = BuildBoard(new Vector3(16f, Kerb, -460f), Quaternion.LookRotation(Vector3.forward));
        TowerCheckpoint(akRoot, new Vector3(18f, Kerb, -462f), "Akiba");

        EditorSceneManager.SaveScene(scene, AkibaPath);
        SetBuildScenes();
        AssetDatabase.SaveAssets();
        Physics.SyncTransforms();
        Debug.Log("SKATE_AKIBA_BUILT features=" + featureCount + " materials=" + akMats.Count + " photos=" + (Directory.Exists(AkibaPhotos) ? Directory.GetFiles(AkibaPhotos, "*.png").Length : 0));
    }

    // ---- streets ---------------------------------------------------------------------------------------

    static void AkStreets()
    {
        AkBox(new Vector3(0f, -0.5f, 0f), new Vector3(1400f, 1f, 1400f));
        AK("asphalt").Ground(-Road, -AveLen - 20f, Road, AveLen + 20f, 0f, 8f, 10f);
        foreach (var cz in CrossZ) AK("asphalt").Ground(Front, cz - CrossHalf, 260f, cz + CrossHalf, 0f, 8f, 10f);
        foreach (var cz in CrossZ) AK("asphalt").Ground(-260f, cz - CrossHalf, -Front, cz + CrossHalf, 0f, 8f, 10f);
        foreach (var s in new[] { -1f, 1f })
        {
            float x0 = s > 0 ? Road : -Front, x1 = s > 0 ? Front : -Road;
            AK("pavement").Ground(x0, -AveLen - 20f, x1, AveLen + 20f, Kerb, 4f, 8f);
            AK("tactile").Ground(s * (Road + 1.2f) - 0.3f, -AveLen - 20f, s * (Road + 1.2f) + 0.3f, AveLen + 20f, Kerb + 0.03f, 0.6f, 20f);
            AkBox(new Vector3(s * (Road + Front) / 2f, Kerb / 2f, 0f), new Vector3(Front - Road, Kerb, AveLen * 2f + 40f));
            AK("concrete").Box(new Vector3(s * (Road + 0.1f), Kerb / 2f, 0f), new Vector3(0.2f, Kerb, AveLen * 2f + 40f), Quaternion.identity, 4f, 4f);
        }
        AK("concrete").Ground(-700f, -700f, 700f, -AveLen - 20f, -0.05f, 12f, 60f);
        AK("concrete").Ground(-700f, AveLen + 20f, 700f, 700f, -0.05f, 12f, 60f);
        foreach (var s in new[] { -1f, 1f })
            AK("concrete").Ground(s > 0 ? 260f : -700f, -AveLen - 20f, s > 0 ? 700f : -260f, AveLen + 20f, -0.05f, 12f, 60f);
        // lane markings, the median's edge lines and the crossings
        var w = AK("white", "e");
        for (float z = -AveLen; z < AveLen; z += 8f)
            foreach (var x in new[] { -(LaneIn + LaneOut) / 2f, (LaneIn + LaneOut) / 2f })
                w.Box(new Vector3(x, 0.03f, z), new Vector3(0.18f, 0.02f, 4f), Quaternion.identity, 1f, 1f);
        foreach (var x in new[] { -Median - 0.4f, Median + 0.4f })
            AK("white", "").Box(new Vector3(x, 0.03f, 0f), new Vector3(0.14f, 0.02f, AveLen * 2f), Quaternion.identity, 1f, 1f, new Color32(255, 200, 40, 255));
        foreach (var cz in CrossZ)
            for (float x = -Road + 1f; x < Road; x += 1.6f)
                w.Box(new Vector3(x, 0.03f, cz), new Vector3(0.9f, 0.02f, 6f), Quaternion.identity, 1f, 1f);
        // big quarterpipes across both ends of the street
        foreach (var s in new[] { -1f, 1f })
            QuarterPipe("End wall", Matrix4x4.TRS(new Vector3(0f, 0f, s * (AveLen + 6f)), Quaternion.LookRotation(new Vector3(0f, 0f, s)), Vector3.one), Front * 2f, 4f, 3f);
        // street lamps along the kerbs
        for (float z = -AveLen + 10f; z < AveLen; z += 24f)
            foreach (var s in new[] { -1f, 1f })
            {
                if (Mathf.Abs(z) < RailHalf + 2f) continue;
                Vector3 p = new Vector3(s * (Road + 0.6f), Kerb, z);
                AK("metal").Cylinder(p, p + Vector3.up * 7f, 0.12f, 6, 2f, new Color32(150, 150, 170, 255));
                AK("metal").Cylinder(p + Vector3.up * 7f, p + Vector3.up * 7f + new Vector3(-s * 1.6f, 0.3f, 0f), 0.08f, 6, 2f, new Color32(150, 150, 170, 255));
                AK("white", "e").Box(p + new Vector3(-s * 1.8f, 7.2f, 0f), new Vector3(0.7f, 0.2f, 0.4f), Quaternion.identity, 1f, 1f, new Color32(255, 240, 200, 255));
                var cap = new GameObject("Lamp post").AddComponent<CapsuleCollider>();
                cap.transform.SetParent(akCol, false); cap.transform.position = p + Vector3.up * 3.5f; cap.radius = 0.14f; cap.height = 7f;
            }
        // guard rails along the kerbs (grindable), with gaps for the crossings
        foreach (var s in new[] { -1f, 1f })
        {
            var stops = new List<float>(CrossZ) { 0f };
            stops.Sort();
            float zs = -AveLen;
            var spans = new List<Vector2>();
            foreach (var cz in stops) { float half = cz == 0f ? RailHalf : CrossHalf + 2f; spans.Add(new Vector2(zs, cz - half)); zs = cz + half; }
            spans.Add(new Vector2(zs, AveLen));
            foreach (var sp in spans)
                for (float z = sp.x + 8f; z < sp.y - 8f; z += 40f)
                    Rail("Guard rail", new[] { new Vector3(s * (Road + 0.35f), Kerb + 0.75f, z), new Vector3(s * (Road + 0.35f), Kerb + 0.75f, Mathf.Min(z + 24f, sp.y - 8f)) });
        }
    }

    // ---- the railway, the station and the train ---------------------------------------------------------

    static void AkRailway()
    {
        float half = 560f;
        var c = AK("concrete");
        c.Box(new Vector3(0f, AkibaDeck - 0.7f, 0f), new Vector3(half * 2f, 1.4f, 10f), Quaternion.identity, 6f, 6f, null, true, true);
        AkBox(new Vector3(0f, AkibaDeck - 0.7f, 0f), new Vector3(half * 2f, 1.4f, 10f));
        foreach (var s in new[] { -1f, 1f })
        {
            c.Box(new Vector3(0f, AkibaDeck + 0.6f, s * 4.85f), new Vector3(half * 2f, 1.2f, 0.3f), Quaternion.identity, 6f, 6f);
            AkBox(new Vector3(0f, AkibaDeck + 0.6f, s * 4.85f), new Vector3(half * 2f, 1.2f, 0.3f));
            AK("posters", "e").Box(new Vector3(0f, AkibaDeck - 1f, s * 5.12f), new Vector3(half * 2f, 1.2f, 0.02f), Quaternion.identity, 4f, 1.2f);
        }
        for (float x = -half + 12f; x < half; x += 24f)
        {
            if (Mathf.Abs(x) < Road + 1f) continue;
            c.Box(new Vector3(x, (AkibaDeck - 1.4f) / 2f, 0f), new Vector3(1.8f, AkibaDeck - 1.4f, 1.8f), Quaternion.identity, 3f, 3f);
            AkBox(new Vector3(x, (AkibaDeck - 1.4f) / 2f, 0f), new Vector3(1.8f, AkibaDeck - 1.4f, 1.8f));
            AK("graffiti_" + AI(0, 6), "").Panel(new Vector3(x, 2.2f, -1.02f), Rt(Vector3.back) * 1.6f, Vector3.up * 0.8f);
        }
        foreach (var sx in new[] { -1f, 1f })
        {
            c.Box(new Vector3(sx * (Road + 0.8f), (AkibaDeck - 1.4f) / 2f, 0f), new Vector3(1.4f, AkibaDeck - 1.4f, 6f), Quaternion.identity, 3f, 3f);
            AkBox(new Vector3(sx * (Road + 0.8f), (AkibaDeck - 1.4f) / 2f, 0f), new Vector3(1.4f, AkibaDeck - 1.4f, 6f));
        }
        foreach (var s in new[] { -1f, 1f })
            AK("station_sign", "e").Panel(new Vector3(0f, AkibaDeck - 0.6f, s * 5.15f), Rt(new Vector3(0f, 0f, s)) * 8f, Vector3.up * 2f);
        for (float x = -half; x < half; x += 1.5f)
            foreach (var tz in new[] { -2.5f, 2.5f })
                AK("concrete").Box(new Vector3(x, AkibaDeck + 0.05f, tz), new Vector3(0.3f, 0.1f, 2.4f), Quaternion.identity, 1f, 1f);
        foreach (var tz in new[] { -2.5f, 2.5f })
            foreach (var rz in new[] { -0.72f, 0.72f })
                Rail("Track", new[] { new Vector3(-half, AkibaDeck + 0.18f, tz + rz), new Vector3(half, AkibaDeck + 0.18f, tz + rz) }, false);

        // the station
        float sx0 = -150f, sx1 = -36f;
        foreach (var s in new[] { -1f, 1f })
        {
            Vector3 pc = new Vector3((sx0 + sx1) / 2f, AkibaDeck + 0.5f, s * 7.6f);
            AK("concrete").Box(pc, new Vector3(sx1 - sx0, 1f, 5f), Quaternion.identity, 4f, 4f);
            AkBox(pc, new Vector3(sx1 - sx0, 1f, 5f));
            AK("tactile").Ground(sx0, s > 0 ? 5.4f : -6.0f, sx1, s > 0 ? 6.0f : -5.4f, AkibaDeck + 1.03f, 0.6f, 10f);
            for (float x = sx0 + 6f; x < sx1; x += 12f)
            {
                AK("metal").Box(new Vector3(x, AkibaDeck + 4.5f, s * 9.6f), new Vector3(0.4f, 7f, 0.4f), Quaternion.identity, 1f, 1f);
                AkBox(new Vector3(x, AkibaDeck + 4.5f, s * 9.6f), new Vector3(0.4f, 7f, 0.4f));
                AK("station_sign", "e").Panel(new Vector3(x + 6f, AkibaDeck + 3.6f, s * 5.4f), Vector3.right * -s * 1.8f, Vector3.up * 0.45f, null, true);
            }
        }
        AK("roof").Box(new Vector3((sx0 + sx1) / 2f, AkibaDeck + 8.2f, 0f), new Vector3(sx1 - sx0 + 4f, 0.6f, 22f), Quaternion.identity, 8f, 8f, null, true, true);
        AkBox(new Vector3((sx0 + sx1) / 2f, AkibaDeck + 8.2f, 0f), new Vector3(sx1 - sx0 + 4f, 0.6f, 22f));
        AkParapet(Rect.MinMaxRect(sx0 - 2f, -11f, sx1 + 2f, 11f), AkibaDeck + 8.5f, 0f);
        foreach (var s in new[] { -1f, 1f })
        {
            Vector3 sc = new Vector3((sx0 + sx1) / 2f, 0f, s * 14f);
            FrontWall(AK("fac_tower_0"), sc, new Vector3(0f, 0f, s), sx1 - sx0, 4f, AkibaDeck - 1.4f, 16f, 21f);
            FrontWall(AK("shop_" + AI(0, 8), "e"), sc, new Vector3(0f, 0f, s), sx1 - sx0, 0f, 4f, 5.3f, 4f);
            AK("station_sign", "e").Panel(new Vector3((sx0 + sx1) / 2f, AkibaDeck - 3f, s * 14.15f), Rt(new Vector3(0f, 0f, s)) * 10f, Vector3.up * 2.5f);
        }
        AkBox(new Vector3((sx0 + sx1) / 2f, (AkibaDeck - 1.4f) / 2f, 0f), new Vector3(sx1 - sx0, AkibaDeck - 1.4f, 28f));
        float stairX = sx1 - 8f, run = 22f, top = AkibaDeck + 1f, z0 = 14f;
        int steps = 36;
        for (int i = 0; i < steps; i++)
        {
            float sh = top * (steps - i) / steps, za = z0 + run * i / steps, zb = z0 + run * (i + 1) / steps;
            AK("concrete").Box(new Vector3(stairX, sh / 2f, (za + zb) / 2f), new Vector3(5f, sh, zb - za), Quaternion.identity, 3f, 3f);
        }
        float slope = Mathf.Atan2(top, run) * Mathf.Rad2Deg, len = Mathf.Sqrt(top * top + run * run);
        AkBox(new Vector3(stairX, top / 2f - 0.15f, z0 + run / 2f), new Vector3(5f, 0.3f, len), Quaternion.Euler(slope, 0f, 0f));
        AK("concrete").Box(new Vector3(stairX, top - 0.5f, 11.5f), new Vector3(5f, 1f, 5f), Quaternion.identity, 3f, 3f);
        AkBox(new Vector3(stairX, top - 0.5f, 11.5f), new Vector3(5f, 1f, 5f));
        foreach (var hx in new[] { stairX - 2.4f, stairX + 2.4f })
            Rail("Stair handrail", new[] { new Vector3(hx, top + 0.9f, 10f), new Vector3(hx, top + 0.9f, z0), new Vector3(hx, 0.9f + Kerb, z0 + run), new Vector3(hx, 0.9f + Kerb, z0 + run + 2f) });
        TowerCheckpoint(akRoot, new Vector3(sx1 - 14f, AkibaDeck + 1f, 7.6f), "Akihabara station");

        var go = new GameObject("Train", typeof(Rigidbody), typeof(Mover));
        go.transform.SetParent(akRoot, false);
        go.GetComponent<Rigidbody>().isKinematic = true;
        var tk = new PSXKit();
        float carLen = 19f, w = 2.9f, h = 3.5f;
        for (int i = -2; i <= 2; i++)
        {
            float cz = i * (carLen + 0.8f);
            foreach (var sx in new[] { -1f, 1f })
                tk.Panel(new Vector3(sx * w / 2f, h / 2f + 0.4f, cz), Rt(new Vector3(sx, 0f, 0f)) * carLen / 2f, Vector3.up * h / 2f);
            tk.Box(new Vector3(0f, h / 2f + 0.4f, cz), new Vector3(w - 0.02f, h, carLen), Quaternion.identity, 50f, 50f, new Color32(200, 204, 214, 255), true, false);
            var bc = go.AddComponent<BoxCollider>();
            bc.center = new Vector3(0f, h / 2f + 0.4f, cz); bc.size = new Vector3(w, h, carLen);
        }
        var tm = tk.Build("Train");
        SaveFeatureMesh(tm);
        go.AddComponent<MeshFilter>().sharedMesh = tm;
        go.AddComponent<MeshRenderer>().sharedMaterial = AkMat("train_side", "");
        var m = go.GetComponent<Mover>();
        m.path = new[] { new Vector3(-520f, AkibaDeck, 2.5f), new Vector3((sx0 + sx1) / 2f, AkibaDeck, 2.5f), new Vector3(520f, AkibaDeck, 2.5f) };
        m.loop = false; m.speed = 14f; m.wait = 8f; m.easeIn = 50f; m.turn = false;
        m.stops = new[] { 520f + (sx0 + sx1) / 2f };
        go.transform.rotation = Quaternion.LookRotation(Vector3.right);
    }

    // ---- buildings along the main street ---------------------------------------------------------------

    // the special buildings: the porch building on the route, the skyscraper you climb on the flying
    // car, and the tall ones carrying the pylons for the power lines over the top
    static readonly Rect EaLot = Rect.MinMaxRect(Front, -384f, Front + 30f, -330f);
    static readonly Rect W1Lot = Rect.MinMaxRect(-Front - 32f, -306f, -Front, -196f);
    static readonly Rect E2Lot = Rect.MinMaxRect(Front, -150f, Front + 40f, -104f);
    static readonly Rect W3Lot = Rect.MinMaxRect(-Front - 40f, 40f, -Front, 100f);
    static readonly Rect E4Lot = Rect.MinMaxRect(Front, 196f, Front + 40f, 262f);
    static readonly Rect W5Lot = Rect.MinMaxRect(-Front - 36f, 336f, -Front, 404f);
    static readonly Rect E6Lot = Rect.MinMaxRect(Front, 360f, Front + 34f, 420f);
    const float EaH = 22f, W1H = 90f, E2H = 150f, W3H = 180f, E4H = 210f, W5H = 160f, E6H = 130f;
    static readonly List<(Rect, float)> akSkyscrapers = new List<(Rect, float)>();
    static readonly float[] BridgeZ = { -250f, -100f, 60f, 240f, 440f };
    static float VentZ(Rect lot) { return Reserved(lot.center.y + 8f, 6f) ? lot.center.y - 8f : lot.center.y + 8f; }

    static void AkBuildings()
    {
        akSkyscrapers.Clear();
        AkTower(EaLot, EaH, -1f, false);
        foreach (var t in new[] { (W1Lot, W1H, 1f), (E2Lot, E2H, -1f), (W3Lot, W3H, 1f), (E4Lot, E4H, -1f), (W5Lot, W5H, 1f), (E6Lot, E6H, -1f) })
        {
            float vz = VentZ(t.Item1);
            akNoStall.Add(new Vector3(-t.Item3, vz - 4f, vz + 4f));   // the updraft vent in front
            AkTower(t.Item1, t.Item2, t.Item3, true);
            akSkyscrapers.Add((t.Item1, t.Item2));
        }
        var specials = new[] { EaLot, W1Lot, E2Lot, W3Lot, E4Lot, W5Lot, E6Lot, Rect.MinMaxRect(-50f, 420f, -16f, 470f) };
        foreach (var side in new[] { -1f, 1f })
        {
            float z = -AveLen + 4f;
            while (z < AveLen - 6f)
            {
                float w = AR(12f, 24f);
                float z1 = Mathf.Min(z + w, AveLen - 4f);
                bool blocked = Mathf.Abs(z) < RailHalf + 1f || Mathf.Abs(z1) < RailHalf + 1f || (z < 0f && z1 > 0f);
                foreach (var cz in CrossZ) if (z1 > cz - CrossHalf - 1f && z < cz + CrossHalf + 1f) blocked = true;
                Rect lot = side > 0 ? Rect.MinMaxRect(Front, z, Front + AR(20f, 36f), z1) : Rect.MinMaxRect(-Front - AR(20f, 36f), z, -Front, z1);
                foreach (var sp in specials) if (sp.Overlaps(lot)) blocked = true;
                // most are mid-rise, some tall (the city goes up)
                float h = ark.NextDouble() < 0.25 ? AR(50f, 110f) : AR(14f, 40f);
                if (!blocked) AkTower(lot, h, -side, h > 50f);
                z = z1 + (ark.NextDouble() < 0.15 ? 3f : 0f);
            }
        }
    }

    // a building: a shopfront at street level, a photo facade above, signs sticking out over the street,
    // a sign band or two, an LED ticker, a billboard on the roof; stalls and machines on the pavement in
    // front; sometimes a balcony with a grindable railing
    static void AkTower(Rect lot, float h, float face, bool tall)
    {
        Vector3 n = new Vector3(face, 0f, 0f);
        float fx = face < 0 ? lot.xMin : lot.xMax;
        float w = lot.height;
        AkBox(new Vector3(lot.center.x, h / 2f, lot.center.y), new Vector3(lot.width, h, lot.height));
        string fac = tall ? "fac_tower_" + AI(0, 4) : "facade_" + AI(0, 6);
        string sideTex = tall ? fac : (ark.NextDouble() < 0.5 ? "fac_side" : "fac_apartment_" + AI(0, 2));
        float tu = tall ? 16f : 12f, tv = tall ? 21f : 16f;
        Vector3 fc = new Vector3(fx, 0f, lot.center.y);
        FrontWall(AK("shop_" + AI(0, 8), "e"), fc, n, w, 0f, 3.6f, 4.8f, 3.6f);
        FrontWall(AK(fac), fc, n, w, 3.6f, h, tu, tv, 3.6f);
        // sides and back
        var sk = AK(sideTex);
        FrontWall(sk, new Vector3(lot.center.x, 0f, lot.yMin), Vector3.back, lot.width, 0f, h, tu, tv);
        FrontWall(sk, new Vector3(lot.center.x, 0f, lot.yMax), Vector3.forward, lot.width, 0f, h, tu, tv);
        FrontWall(sk, new Vector3(face < 0 ? lot.xMax : lot.xMin, 0f, lot.center.y), -n, w, 0f, h, tu, tv);
        AK("roof").Ground(lot.xMin, lot.yMin, lot.xMax, lot.yMax, h, 8f, 12f);
        AkParapet(lot, h, face, false);
        akLots.Add((lot, h, face));

        // an LED ticker across the shopfront, sign bands, signs sticking out
        AK("led_" + AI(0, 3), "s").Panel(new Vector3(fx + face * 0.12f, 3.85f, lot.center.y), Rt(n) * (w / 2f - 0.3f), Vector3.up * 0.22f, null, false, new Rect(0f, 0f, w / 6.4f, 1f));
        int bands = AI(1, tall ? 3 : 4);
        for (int b = 0; b < bands; b++)
        {
            float y = AR(5f, Mathf.Min(Mathf.Max(6f, h - 3f), 30f));
            float bw = Mathf.Min(w - 1f, AR(5f, 9f));
            AK("sign_h_" + AI(0, 6), ark.NextDouble() < 0.3 ? "f" : "e").Panel(new Vector3(fx + face * 0.2f, y, lot.center.y + AR(-(w - bw) / 2f, (w - bw) / 2f)),
                Rt(n) * (bw / 2f), Vector3.up * (bw / 5.4f));
        }
        int vs = Mathf.Clamp(Mathf.RoundToInt(w / 6f), 1, 4);
        for (int i = 0; i < vs; i++)
        {
            float z = Mathf.Lerp(lot.yMin + 1f, lot.yMax - 1f, (i + 0.5f) / vs);
            float sh = Mathf.Min(AR(3.5f, 6f), h - 5f);
            if (sh < 2.5f) continue;
            float y = AR(4.5f, Mathf.Max(4.6f, Mathf.Min(h, 30f) - sh - 0.5f)) + sh / 2f;
            string st = ark.NextDouble() < 0.35 ? "f" : "e";
            string tex = "sign_v_" + AI(0, 8);
            Vector3 sc = new Vector3(fx + face * 0.85f, y, z);
            // a sign on each side of a thin frame (not inside it)
            AK(tex, st).Panel(sc + Vector3.forward * 0.09f, Rt(Vector3.forward) * 0.65f, Vector3.up * sh / 2f);
            AK(tex, st).Panel(sc + Vector3.back * 0.09f, Rt(Vector3.back) * 0.65f, Vector3.up * sh / 2f);
            AK("metal").Box(sc, new Vector3(1.34f, sh + 0.12f, 0.1f), Quaternion.identity, 1f, 1f);
        }
        if (ark.NextDouble() < 0.4)
            AK("graffiti_" + AI(0, 6), "").Panel(new Vector3(lot.center.x, AR(4.5f, 7f), face < 0 ? lot.yMin - 0.12f : lot.yMax + 0.12f), Rt(face < 0 ? Vector3.back : Vector3.forward) * 2.8f, Vector3.up * 1.4f);
        if (ark.NextDouble() < 0.65)
        {
            float bh = AR(6f, tall ? 14f : 10f);
            Vector3 bc = new Vector3(fx - face * 2f, h + 1.5f + bh / 2f, lot.center.y);
            AK("billboard_" + AI(0, 10), ark.NextDouble() < 0.2 ? "f" : "e").Panel(bc + n * 0.14f, Rt(n) * bh / 2f, Vector3.up * bh / 2f);
            AK("metal").Box(bc, new Vector3(0.16f, bh, bh), Quaternion.identity, 2f, 2f);
            foreach (var o in new[] { -bh / 2.5f, bh / 2.5f })
                AK("metal").Box(new Vector3(bc.x - face * 0.4f, h + 0.75f, bc.z + o), new Vector3(0.25f, 1.5f, 0.25f), Quaternion.identity, 1f, 1f);
            AkBox(bc, new Vector3(0.2f, bh, bh));
        }
        AkStalls(fx, lot, face);
        // balconies, and on taller buildings, more of them going up
        if (h > 14f && ark.NextDouble() < 0.6)
            AkPorch(fx, face, AR(7f, Mathf.Min(14f, h - 4f)), lot.center.y + AR(-w / 4f, w / 4f), Mathf.Min(6f, w - 2f));
        if (h > 30f && ark.NextDouble() < 0.6)
            AkPorch(fx, face, AR(20f, Mathf.Min(34f, h - 4f)), lot.center.y + AR(-w / 4f, w / 4f), Mathf.Min(6f, w - 2f));
        if (tall) akAnchors.Add(new Vector3(fx, h, lot.center.y));
    }

    static void AkParapet(Rect lot, float h, float face, bool ends = true)
    {
        var mk = AK("concrete");
        Vector3[] c = { new Vector3(lot.xMin, 0f, lot.yMin), new Vector3(lot.xMax, 0f, lot.yMin), new Vector3(lot.xMax, 0f, lot.yMax), new Vector3(lot.xMin, 0f, lot.yMax) };
        for (int i = 0; i < 4; i++)
        {
            Vector3 a = c[i], b = c[(i + 1) % 4];
            if (face != 0f && Mathf.Abs(a.x - b.x) < 0.01f && Mathf.Abs(a.x - (face < 0 ? lot.xMin : lot.xMax)) < 0.01f) continue;   // street side open
            if (!ends && Mathf.Abs(a.z - b.z) < 0.01f) continue;   // ends open too: ride on from roof to roof
            Vector3 d = (b - a).normalized, inward = Vector3.Cross(Vector3.up, d);
            Vector3 mid = (a + b) / 2f + inward * 0.15f + Vector3.up * (h + 0.3f);
            Quaternion q = Quaternion.LookRotation(d);
            mk.Box(mid, new Vector3(0.3f, 0.6f, Vector3.Distance(a, b)), q, 3f, 3f);
            AkBox(mid, new Vector3(0.3f, 0.6f, Vector3.Distance(a, b)), q);
            Rail("Roof edge", new[] { a + inward * 0.15f + Vector3.up * (h + 0.62f) + d * 0.3f, b + inward * 0.15f + Vector3.up * (h + 0.62f) - d * 0.3f }, false);
        }
    }

    static void AkStalls(float fx, Rect lot, float face)
    {
        Vector3 n = new Vector3(face, 0f, 0f);
        float z = lot.yMin + 0.6f;
        while (z < lot.yMax - 3.2f)
        {
            bool keep = false;
            foreach (var ns in akNoStall) if (Mathf.Sign(ns.x) == -Mathf.Sign(face) && z > ns.y - 4f && z < ns.z) keep = true;
            if (keep) { z += 2f; continue; }
            float kind = (float)ark.NextDouble();
            if (kind < 0.5f)
            {
                // a stall with a lit front and a flat roof (a ledge to ride onto), and a bank up to it
                float sw = AR(3f, 4.5f);
                if (ark.NextDouble() < 0.4 && z + 7.4f + sw < lot.yMax)
                {
                    // a bank up from the pavement onto the stall's roof
                    Wedge("shutter", new Vector3(fx + face * 1.6f, Kerb, z), Vector3.forward, 7f, 2.8f, 2.6f);
                    z += 7.2f;
                }
                Vector3 c = new Vector3(fx + face * 1.4f, 1.3f + Kerb, z + sw / 2f);
                AK("concrete").Box(c, new Vector3(2.8f, 2.6f, sw), Quaternion.identity, 3f, 3f, null, false);
                AK("shop_" + AI(0, 8), "e").Panel(c + n * 1.52f, Rt(n) * sw / 2f, Vector3.up * 1.2f);
                AK("roof").Box(c + Vector3.up * 1.4f + n * 0.4f, new Vector3(3.8f, 0.2f, sw + 0.2f), Quaternion.identity, 3f, 3f);
                AkBox(c + Vector3.up * 0.1f, new Vector3(2.8f, 2.8f, sw));
                var roofCol = AddBox(akCol, "Stall roof", c + Vector3.up * 1.4f + n * 0.4f, new Vector3(3.8f, 0.2f, sw + 0.2f));
                if (ark.NextDouble() < 0.25)
                {
                    // a springy awning: stretched pink canvas that bounces you up to the balconies
                    roofCol.gameObject.AddComponent<Bouncer>().speed = 17f;
                    AK("white", "e").Box(c + Vector3.up * 1.56f + n * 0.4f, new Vector3(3.7f, 0.06f, sw + 0.1f), Quaternion.identity, 1f, 1f, new Color32(255, 110, 190, 255));
                }
                z += sw + 0.3f;
            }
            else if (kind < 0.75f)
            {
                int count = AI(2, 5);
                for (int i = 0; i < count; i++)
                {
                    Vector3 c = new Vector3(fx + face * 0.45f, 0.95f + Kerb, z + 0.5f + i * 1.05f);
                    AK("vending", "e").Panel(c + n * 0.5f, Rt(n) * 0.5f, Vector3.up * 0.95f);
                    AK("metal").Box(c, new Vector3(0.8f, 1.9f, 1f), Quaternion.identity, 1f, 1f, new Color32(220, 60, 70, 255));
                    AkBox(c, new Vector3(0.8f, 1.9f, 1f));
                }
                z += count * 1.05f + 0.6f;
            }
            else
            {
                int count = AI(2, 4);
                Vector3 c = new Vector3(fx + face * 0.35f, 0.9f + Kerb, z + count * 0.6f);
                AK("gacha", "e").Panel(c + n * 0.4f, Rt(n) * count * 0.6f, Vector3.up * 0.9f);
                AK("white").Box(c, new Vector3(0.6f, 1.8f, count * 1.2f), Quaternion.identity, 1f, 1f);
                AkBox(c, new Vector3(0.6f, 1.8f, count * 1.2f));
                z += count * 1.2f + 0.6f;
            }
            z += AR(0.5f, 3f);
        }
    }

    static void AkPorch(float fx, float face, float y, float zc, float w)
    {
        Vector3 n = new Vector3(face, 0f, 0f);
        Vector3 c = new Vector3(fx + face * 1.4f, y - 0.15f, zc);
        AK("concrete").Box(c, new Vector3(2.8f, 0.3f, w), Quaternion.identity, 3f, 3f, null, true, true);
        AkBox(c, new Vector3(2.8f, 0.3f, w));
        Rail("Balcony rail", new[] { new Vector3(fx + face * 2.7f, y + 1f, zc - w / 2f + 0.2f), new Vector3(fx + face * 2.7f, y + 1f, zc + w / 2f - 0.2f) });
        AK("shutter").Panel(new Vector3(fx + face * 0.12f, y + 1.1f, zc), Rt(n) * 0.9f, Vector3.up * 1.1f);
        akAnchors.Add(new Vector3(fx + face * 1.4f, y, zc));
    }

    // ---- side streets ---------------------------------------------------------------------------------

    static void AkSideStreets()
    {
        foreach (var cz in CrossZ)
            foreach (var s in new[] { -1f, 1f })
            {
                foreach (var zs in new[] { -1f, 1f })
                {
                    float x = Front + 2f;
                    while (x < 240f)
                    {
                        float w = AR(9f, 18f), d = AR(10f, 20f), h = ark.NextDouble() < 0.2 ? AR(30f, 60f) : AR(8f, 24f);
                        Rect lot = s > 0
                            ? Rect.MinMaxRect(x, zs > 0 ? cz + CrossHalf : cz - CrossHalf - d, x + w, zs > 0 ? cz + CrossHalf + d : cz - CrossHalf)
                            : Rect.MinMaxRect(-x - w, zs > 0 ? cz + CrossHalf : cz - CrossHalf - d, -x, zs > 0 ? cz + CrossHalf + d : cz - CrossHalf);
                        AkSideBuilding(lot, h, zs > 0 ? -1f : 1f);
                        x += w + (ark.NextDouble() < 0.3 ? 3f : 0.5f);
                    }
                }
                foreach (var zs in new[] { -1f, 1f })
                {
                    var poles = new List<Vector3>();
                    for (float x = Front + 6f; x < 236f; x += 22f) poles.Add(new Vector3(s * x, 0f, cz + zs * (CrossHalf - 0.6f)));
                    foreach (var p in poles)
                    {
                        AK("metal").Cylinder(p, p + Vector3.up * 9f, 0.16f, 6, 3f, new Color32(150, 140, 130, 255));
                        AK("metal").Box(p + Vector3.up * 8.6f, new Vector3(0.14f, 0.14f, 1.8f), Quaternion.identity, 1f, 1f);
                        AK("metal").Cylinder(p + Vector3.up * 7f, p + Vector3.up * 7.8f, 0.35f, 8, 1f, new Color32(130, 130, 140, 255));
                        var cap = new GameObject("Pole").AddComponent<CapsuleCollider>();
                        cap.transform.SetParent(akCol, false); cap.transform.position = p + Vector3.up * 4.5f; cap.radius = 0.18f; cap.height = 9f;
                    }
                    foreach (var off in new[] { -0.6f, 0.6f })
                    {
                        var line = new List<Vector3>();
                        for (int i = 0; i < poles.Count - 1; i++)
                        {
                            var seg = Catenary(poles[i] + new Vector3(0f, 8.6f, off), poles[i + 1] + new Vector3(0f, 8.6f, off), 0.7f, 8);
                            for (int k = i == 0 ? 0 : 1; k < seg.Length; k++) line.Add(seg[k]);
                        }
                        Rail("Power line", line.ToArray(), false);
                        AK("white").Tube(line, 0.03f, 4, 4f, new Color32(30, 26, 40, 255));
                    }
                }
                // a barrier across the side street where it leaves the main street: slide under it
                float bx = s * (Front + 3f);
                AK("hazard", "e").Box(new Vector3(bx, 1.25f, cz), new Vector3(0.3f, 0.5f, CrossHalf * 2f), Quaternion.identity, 1f, 0.5f);
                foreach (var zz in new[] { -CrossHalf + 0.3f, CrossHalf - 0.3f })
                    AK("metal").Box(new Vector3(bx, 0.75f, cz + zz), new Vector3(0.2f, 1.5f, 0.2f), Quaternion.identity, 1f, 1f);
                AkBox(new Vector3(bx, 1.25f, cz), new Vector3(0.3f, 0.5f, CrossHalf * 2f));
                AkBox(new Vector3(bx, 0.75f, cz - CrossHalf + 0.3f), new Vector3(0.2f, 1.5f, 0.2f));
                AkBox(new Vector3(bx, 0.75f, cz + CrossHalf - 0.3f), new Vector3(0.2f, 1.5f, 0.2f));
                // ramps and humps all along the side street
                for (float x = 40f; x < 230f; x += AR(24f, 40f))
                {
                    if (ark.NextDouble() < 0.5) Hump("Kicker", new Vector3(s * x, 0f, cz + AR(-4f, 4f)), new Vector3(s, 0f, 0f), AR(3.5f, 5f), AR(22f, 32f), 4f, RampSide2);
                    else Wedge("concrete", new Vector3(s * x, 0f, cz + AR(-4f, 4f)), new Vector3(s, 0f, 0f), AR(4f, 7f), AR(1f, 2f), 3.5f);
                }
            }
    }

    static void AkSideBuilding(Rect lot, float h, float face)
    {
        AkBox(new Vector3(lot.center.x, h / 2f, lot.center.y), new Vector3(lot.width, h, lot.height));
        string fac = h > 28f ? "fac_tower_" + AI(0, 4) : (ark.NextDouble() < 0.5 ? "fac_apartment_" + AI(0, 2) : "facade_" + AI(0, 6));
        float tu = h > 28f ? 16f : 12f, tv = h > 28f ? 21f : 16f;
        Vector3 n = new Vector3(0f, 0f, face);
        float fz = face < 0 ? lot.yMin : lot.yMax;
        Vector3 fc = new Vector3(lot.center.x, 0f, fz);
        FrontWall(AK(ark.NextDouble() < 0.6 ? "shop_" + AI(0, 8) : "shutter", "e"), fc, n, lot.width, 0f, 3.4f, 4.8f, 3.4f);
        FrontWall(AK(fac), fc, n, lot.width, 3.4f, h, tu, tv, 3.4f);
        var sk = AK("fac_side");
        FrontWall(sk, new Vector3(lot.xMin, 0f, lot.center.y), Vector3.left, lot.height, 0f, h, 12f, 16f);
        FrontWall(sk, new Vector3(lot.xMax, 0f, lot.center.y), Vector3.right, lot.height, 0f, h, 12f, 16f);
        FrontWall(sk, new Vector3(lot.center.x, 0f, face < 0 ? lot.yMax : lot.yMin), -n, lot.width, 0f, h, 12f, 16f);
        AK("roof").Ground(lot.xMin, lot.yMin, lot.xMax, lot.yMax, h, 8f, 12f);
        if (ark.NextDouble() < 0.5)
        {
            string tex = "sign_v_" + AI(0, 8), st = ark.NextDouble() < 0.4 ? "f" : "e";
            Vector3 sc = new Vector3(lot.xMin + 1f, Mathf.Min(h - 3f, 7f), fz + face * 0.75f);
            AK(tex, st).Panel(sc + Vector3.right * 0.09f, Rt(Vector3.right) * 0.55f, Vector3.up * 2.2f);
            AK(tex, st).Panel(sc + Vector3.left * 0.09f, Rt(Vector3.left) * 0.55f, Vector3.up * 2.2f);
            AK("metal").Box(sc, new Vector3(0.1f, 4.5f, 1.14f), Quaternion.identity, 1f, 1f);
        }
        if (ark.NextDouble() < 0.35)
            AK("graffiti_" + AI(0, 6), "").Panel(new Vector3(lot.center.x, 1.7f, fz + face * 0.12f), Rt(n) * 2f, Vector3.up * 1f);
        akAnchors.Add(new Vector3(lot.center.x, h, fz));
    }

    // ---- the flow: things that throw you from one place to the next -----------------------------------

    // a glowing arrow on the ground that shoots you off the way it points
    static void BoostArrow(Vector3 at, Vector3 dir, float speed)
    {
        dir = new Vector3(dir.x, 0f, dir.z).normalized;
        Vector3 side = Rt(dir);
        var k = AK("white", "e");
        k.Box(at + Vector3.up * 0.03f, new Vector3(2.4f, 0.04f, 3.2f), Quaternion.LookRotation(dir), 1f, 1f, new Color32(20, 40, 70, 255));
        for (int i = 0; i < 3; i++)
        {
            Vector3 c = at + dir * (i - 1f) * 0.95f + Vector3.up * 0.07f;
            // a chevron: two bars meeting at the front
            foreach (var s in new[] { -1f, 1f })
                k.Box(c + side * s * 0.45f, new Vector3(0.22f, 0.04f, 1.1f), Quaternion.LookRotation(dir + side * s * 0.9f), 1f, 1f, new Color32(60, 240, 255, 255));
        }
        var col = AddBox(akCol, "Boost pad", at + Vector3.up * 0.03f, new Vector3(2.4f, 0.06f, 3.2f), Quaternion.LookRotation(dir));
        var pad = col.gameObject.AddComponent<BoostPad>();
        pad.direction = dir; pad.speed = speed;
    }

    // a giant capsule toy, half clear and half coloured: land on it and it bounces you high
    static void Capsule(Vector3 at, float r)
    {
        var k = new SkateMeshKit();
        Color32 col = new[] { new Color32(255, 70, 160, 255), new Color32(60, 230, 255, 255), new Color32(255, 214, 40, 255), new Color32(140, 255, 120, 255) }[AI(0, 4)];
        Vector3 c = at + Vector3.up * r * 0.85f;
        k.Ellipsoid(c, new Vector3(r, r * 0.85f, r), Quaternion.identity, 14, 10, col);
        k.Box(c, new Vector3(r * 2.02f, 0.12f, r * 2.02f), Quaternion.identity, new Color32(255, 255, 255, 255));
        k.Ellipsoid(c + Vector3.up * r * 0.25f + new Vector3(-r * 0.3f, 0f, -r * 0.3f), Vector3.one * r * 0.18f, Quaternion.identity, 8, 5, new Color32(255, 255, 255, 255));
        var mesh = k.Build("Capsule");
        SaveFeatureMesh(mesh);
        MeshObject("Capsule", akRoot, mesh, AkMat("white", "e"), outlineMat);
        var sc = new GameObject("Capsule").AddComponent<SphereCollider>();
        sc.transform.SetParent(akCol, false);
        sc.transform.position = c; sc.radius = r * 0.9f;
        sc.gameObject.AddComponent<Bouncer>().speed = 21f;
    }

    // a vent with a column of air blowing up out of it, steam rising
    static void Vent(Vector3 at, float height, float radius = 2f)
    {
        var k = AK("metal");
        k.Box(at + Vector3.up * 0.12f, new Vector3(radius * 1.6f, 0.24f, radius * 1.6f), Quaternion.identity, 1f, 1f);
        for (float x = -radius * 0.6f; x <= radius * 0.6f; x += 0.4f)
            AK("white", "e").Box(at + new Vector3(x, 0.25f, 0f), new Vector3(0.08f, 0.02f, radius * 1.4f), Quaternion.identity, 1f, 1f, new Color32(60, 240, 255, 255));
        AkBox(at + Vector3.up * 0.12f, new Vector3(radius * 1.6f, 0.24f, radius * 1.6f));
        var go = new GameObject("Updraft", typeof(Updraft), typeof(ParticleSystem));
        go.transform.SetParent(akRoot, false);
        go.transform.position = at;
        var u = go.GetComponent<Updraft>();
        u.radius = radius; u.height = height; u.lift = Mathf.Clamp(height * 0.7f, 14f, 30f);
        var ps = go.GetComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = true; main.playOnAwake = true; main.prewarm = true;
        main.startLifetime = Mathf.Min(4f, height / 10f);
        main.startSpeed = new ParticleSystem.MinMaxCurve(8f, 12f);
        main.startSize = new ParticleSystem.MinMaxCurve(0.4f, 1.2f);
        main.startColor = new ParticleSystem.MinMaxGradient(new Color(0.75f, 0.95f, 1f, 0.35f), new Color(1f, 1f, 1f, 0.2f));
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.maxParticles = 300;
        var em = ps.emission; em.rateOverTime = 40f;
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = radius * 0.8f;
        shape.rotation = new Vector3(-90f, 0f, 0f);
        var fade = ps.colorOverLifetime; fade.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                     new[] { new GradientAlphaKey(0.6f, 0f), new GradientAlphaKey(0f, 1f) });
        fade.color = grad;
        go.GetComponent<ParticleSystemRenderer>().sharedMaterial = Mat("Sparks", "Sprites/Default");
    }

    // a pedestrian bridge over the main street (a classic Japanese one: pale green steel), with ramps
    // down to the pavement either side, and railings to grind
    static void FootBridge(float z)
    {
        float y = 6f, half = 1.6f, x1 = Road + 3.2f;
        Color32 green = new Color32(150, 210, 180, 255);
        AK("white").Box(new Vector3(0f, y - 0.25f, z), new Vector3(x1 * 2f + 2.8f, 0.5f, half * 2f), Quaternion.identity, 1f, 1f, green, true, true);
        AkBox(new Vector3(0f, y - 0.25f, z), new Vector3(x1 * 2f + 2.8f, 0.5f, half * 2f));
        // ads along both sides
        foreach (var s in new[] { -1f, 1f })
        {
            AK("billboard_" + AI(0, 10), "e").Panel(new Vector3(-6f, y - 0.9f, z + s * (half + 0.05f)), Rt(new Vector3(0f, 0f, s)) * 5f, Vector3.up * 0.7f);
            AK("billboard_" + AI(0, 10), "e").Panel(new Vector3(6f, y - 0.9f, z + s * (half + 0.05f)), Rt(new Vector3(0f, 0f, s)) * 5f, Vector3.up * 0.7f);
            AK("white").Box(new Vector3(0f, y - 0.9f, z + s * half), new Vector3(x1 * 2f, 1.4f, 0.06f), Quaternion.identity, 1f, 1f, green);
            Rail("Bridge railing", new[] { new Vector3(-x1 - 1f, y + 1f, z + s * (half - 0.1f)), new Vector3(x1 + 1f, y + 1f, z + s * (half - 0.1f)) });
        }
        foreach (var sx in new[] { -1f, 1f })
        {
            // a pillar each side, then the ramp down along the pavement
            AK("white").Box(new Vector3(sx * x1, (y - 0.5f) / 2f, z), new Vector3(0.6f, y - 0.5f, 0.6f), Quaternion.identity, 1f, 1f, green);
            AkBox(new Vector3(sx * x1, (y - 0.5f) / 2f, z), new Vector3(0.6f, y - 0.5f, 0.6f));
            float dz = sx > 0f ? 1f : -1f;
            Vector3 bottom = new Vector3(sx * x1, Kerb, z + dz * (half + 20f));
            Wedge("concrete", bottom, new Vector3(0f, 0f, -dz), 20f, y - Kerb, 2.8f);
            foreach (var e in new[] { -1.45f, 1.45f })
                Rail("Bridge ramp rail", new[] { bottom + new Vector3(e, 1f, 0f), new Vector3(sx * x1 + e, y + 1f, z + dz * half) });
        }
        akAnchors.Add(new Vector3(0f, y, z));
    }

    // a string of paper lanterns between two points (a grindable line)
    static void Lanterns(Vector3 a, Vector3 b)
    {
        var line = Catenary(a, b, Vector3.Distance(a, b) * 0.05f, 14);
        Rail("Lantern string", line, false);
        AK("white").Tube(line, 0.03f, 4, 4f, new Color32(40, 30, 30, 255));
        for (int i = 1; i < line.Length - 1; i++)
            AK("white", "e").Ellipsoid(line[i] + Vector3.down * 0.45f, new Vector3(0.28f, 0.38f, 0.28f), 8, 5, i % 3 == 0 ? new Color32(255, 240, 200, 255) : new Color32(255, 70, 60, 255));
    }

    static void AkFlow()
    {
        // pedestrian bridges over the main street
        foreach (var z in BridgeZ) FootBridge(z);

        // updrafts up the skyscrapers: a vent on the pavement in front, blowing you up to a balcony
        foreach (var (lot, h) in akSkyscrapers)
        {
            float face = lot.center.x > 0f ? -1f : 1f, fx = face < 0 ? lot.xMin : lot.xMax;
            float zc = VentZ(lot);
            float top = Mathf.Min(h - 6f, 48f);
            Vent(new Vector3(fx + face * 4.2f, Kerb, zc), top - Kerb + 1.5f, 2.2f);
            AkPorch(fx, face, top, zc, 7f);
        }

        // the rooftops along each side of the street, joined up: where the next roof is a bit higher, a
        // ramp up to it; much higher, a vent on this roof that blows you up to it
        int ramps = 0, vents = 0;
        foreach (var side in new[] { -1f, 1f })
        {
            var row = akLots.FindAll(l => Mathf.Sign(l.Item1.center.x) == side);
            row.Sort((p, q) => p.Item1.yMin.CompareTo(q.Item1.yMin));
            for (int i = 0; i < row.Count - 1; i++)
            {
                var (la, ha, _) = row[i];
                var (lb, hb, _) = row[i + 1];
                if (lb.yMin - la.yMax > 4f) continue;   // not neighbours
                bool up = hb > ha;
                var (lo, hl) = up ? (la, ha) : (lb, hb);
                var (hi, hh) = up ? (lb, hb) : (la, ha);
                float dh = hh - hl;
                if (dh < 0.8f) continue;
                float x0 = Mathf.Max(lo.xMin, hi.xMin) + 1f, x1 = Mathf.Min(lo.xMax, hi.xMax) - 1f;
                if (x1 - x0 < 3f) continue;
                float xc = (x0 + x1) / 2f, wdt = Mathf.Min(4f, x1 - x0);
                Vector3 dir = up ? Vector3.forward : Vector3.back;   // from the low roof towards the high one
                float edge = up ? lo.yMax : lo.yMin;
                float len = dh * 2.6f;
                if (dh <= 7f && len + 1f < lo.height)
                {
                    Wedge("roof", new Vector3(xc, hl, edge - dir.z * len), dir, len, dh + 0.05f, wdt);
                    ramps++;
                }
                else
                {
                    Vent(new Vector3(xc, hl, edge - dir.z * 3.5f), dh + 5f, 2f);
                    vents++;
                }
            }
        }

        // lantern strings across the side streets, roof edge to roof edge, and torii gates where they start
        foreach (var cz in CrossZ)
            foreach (var s in new[] { -1f, 1f })
            {
                for (float x = Front + 14f; x < 200f; x += AR(16f, 26f))
                {
                    float y1 = AR(5.2f, 6.6f), y2 = AR(5.2f, 6.6f);
                    Lanterns(new Vector3(s * x, y1, cz - CrossHalf), new Vector3(s * (x + AR(6f, 14f)), y2, cz + CrossHalf));
                }
                // a torii gate over the side street: its top beam is a rail
                float tx = s * (Front + 9f);
                Color32 red = new Color32(230, 50, 40, 255), black = new Color32(30, 25, 30, 255);
                foreach (var zz in new[] { -CrossHalf + 1.2f, CrossHalf - 1.2f })
                {
                    AK("white").Cylinder(new Vector3(tx, 0f, cz + zz), new Vector3(tx, 6.4f, cz + zz), 0.35f, 10, 2f, red);
                    var cap = new GameObject("Torii post").AddComponent<CapsuleCollider>();
                    cap.transform.SetParent(akCol, false); cap.transform.position = new Vector3(tx, 3.2f, cz + zz); cap.radius = 0.35f; cap.height = 6.4f;
                }
                AK("white").Box(new Vector3(tx, 5.4f, cz), new Vector3(0.5f, 0.4f, CrossHalf * 2f - 1f), Quaternion.identity, 1f, 1f, red);
                AK("white").Box(new Vector3(tx, 6.55f, cz), new Vector3(0.7f, 0.35f, CrossHalf * 2f + 2f), Quaternion.identity, 1f, 1f, black);
                AkBox(new Vector3(tx, 6.55f, cz), new Vector3(0.7f, 0.35f, CrossHalf * 2f + 2f));
                Rail("Torii", new[] { new Vector3(tx, 6.75f, cz - CrossHalf - 0.8f), new Vector3(tx, 6.75f, cz + CrossHalf + 0.8f) }, false);
                // a ramen cart (its roof's a ledge) and a row of bikes in a rack (grindable)
                float rx = s * AR(Front + 30f, 120f);
                Vector3 cart = new Vector3(rx, 0f, cz + CrossHalf - 1.4f);
                AK("white").Box(cart + Vector3.up * 0.6f, new Vector3(2.6f, 1.2f, 1.4f), Quaternion.identity, 1f, 1f, new Color32(150, 100, 60, 255));
                AK("shop_4", "e").Panel(cart + new Vector3(0f, 0.6f, -0.71f), Rt(Vector3.back) * 1.25f, Vector3.up * 0.55f);
                AK("white").Box(cart + Vector3.up * 2.25f, new Vector3(3f, 0.15f, 2f), Quaternion.identity, 1f, 1f, new Color32(200, 40, 40, 255));
                foreach (var lx in new[] { -1.1f, 1.1f }) AK("white", "e").Ellipsoid(cart + new Vector3(lx, 1.8f, -1f), new Vector3(0.25f, 0.35f, 0.25f), 8, 5, new Color32(255, 70, 60, 255));
                AkBox(cart + Vector3.up * 0.6f, new Vector3(2.6f, 1.2f, 1.4f));
                AkBox(cart + Vector3.up * 2.25f, new Vector3(3f, 0.15f, 2f));
                float bx = s * AR(Front + 20f, 150f);
                Rail("Bike rack", new[] { new Vector3(bx, 0.7f, cz - CrossHalf + 1f), new Vector3(bx + s * 8f, 0.7f, cz - CrossHalf + 1f) });
                for (float b = 0.5f; b < 8f; b += 0.9f)
                    AK("white").Box(new Vector3(bx + s * b, 0.5f, cz - CrossHalf + 1.6f), new Vector3(0.08f, 0.9f, 1.6f), Quaternion.identity, 1f, 1f, new Color32((byte)AI(60, 255), (byte)AI(60, 255), (byte)AI(60, 255), 255));
            }
        Debug.Log("AKIBA_FLOW roof ramps=" + ramps + " roof vents=" + vents);
    }
    // ---- the median: a strip of junk down the middle of the main street to skate --------------------

    static void AkMedian()
    {
        for (float z = -AveLen + 30f; z < AveLen - 30f; z += AR(10f, 18f))
        {
            if (Mathf.Abs(z) < RailHalf + 6f || Reserved(z)) continue;
            bool cross = false;
            foreach (var cz in CrossZ) if (Mathf.Abs(z - cz) < CrossHalf + 4f) cross = true;
            if (cross) continue;
            float k = (float)ark.NextDouble();
            float dir = ark.NextDouble() < 0.5 ? 1f : -1f;
            if (k < 0.18f)
            {
                // a concrete barrier with a grindable top
                AK("concrete").Box(new Vector3(0f, 0.45f, z), new Vector3(0.6f, 0.9f, 8f), Quaternion.identity, 3f, 3f);
                AkBox(new Vector3(0f, 0.45f, z), new Vector3(0.6f, 0.9f, 8f));
                Rail("Barrier", new[] { new Vector3(0f, 0.92f, z - 3.8f), new Vector3(0f, 0.92f, z + 3.8f) }, false);
                z += 6f;
            }
            else if (k < 0.27f) { BoostArrow(new Vector3(0f, 0f, z), new Vector3(0f, 0f, dir), 28f); z += 4f; }
            else if (k < 0.36f) { Capsule(new Vector3(AR(-1f, 1f), 0f, z), AR(1.4f, 2f)); z += 4f; }
            else if (k < 0.44f) Hump("Road kicker", new Vector3(AR(-1.5f, 1.5f), 0f, z), new Vector3(0f, 0f, dir), AR(3f, 5f), AR(22f, 34f), 3f, RampSide2);
            else if (k < 0.5f) Wedge("metal", new Vector3(AR(-1f, 1f), 0f, z), new Vector3(0f, 0f, dir), AR(3f, 6f), AR(0.8f, 1.8f), 3f);
            else if (k < 0.62f)
            {
                // a wrecked car on its roof, a steel plate leaning on it for a ramp
                Vector3 c = new Vector3(0f, 0.7f, z);
                AK("white").Box(c, new Vector3(1.8f, 1.4f, 4.2f), Quaternion.Euler(0f, AR(-15f, 15f), 0f), 1f, 1f, new Color32((byte)AI(60, 255), (byte)AI(60, 255), (byte)AI(60, 255), 255));
                AkBox(c, new Vector3(1.8f, 1.4f, 4.2f), Quaternion.Euler(0f, 0f, 0f));
                Wedge("metal", new Vector3(0f, 0f, z - dir * 5.6f), new Vector3(0f, 0f, dir), 3.5f, 1.4f, 2f);
                z += 6f;
            }
            else if (k < 0.74f)
            {
                // a pipe on stands (grindable)
                float len = AR(6f, 14f);
                Rail("Pipe", new[] { new Vector3(AR(-1f, 1f), 0.6f, z), new Vector3(AR(-1f, 1f), AR(0.6f, 1.6f), z + len) });
                z += len;
            }
            else if (k < 0.86f)
            {
                // a little funbox
                Funbox("Funbox", Matrix4x4.TRS(new Vector3(0f, 0f, z), Quaternion.LookRotation(new Vector3(0f, 0f, dir)), Vector3.one), 3f);
                z += 10f;
            }
            else
            {
                // a row of traffic cones (no collider: knock through them)
                for (int i = 0; i < 5; i++)
                    AK("white", "e").Cylinder(new Vector3(0f, 0f, z + i * 1.2f), new Vector3(0f, 0.7f, z + i * 1.2f), 0.18f, 6, 1f, new Color32(255, 110, 30, 255));
            }
        }
    }

    // ---- the route: kicker, curving rail, balcony, sign ramp, roof, flying car, the skyscraper's pipe --

    static Vector3[] Spline(Vector3[] ctrl, int perSeg)
    {
        var pts = new List<Vector3>();
        for (int i = 0; i < ctrl.Length - 1; i++)
        {
            Vector3 p0 = ctrl[Mathf.Max(0, i - 1)], p1 = ctrl[i], p2 = ctrl[i + 1], p3 = ctrl[Mathf.Min(ctrl.Length - 1, i + 2)];
            for (int k = 0; k < perSeg; k++)
            {
                float t = k / (float)perSeg, t2 = t * t, t3 = t2 * t;
                pts.Add(0.5f * (2f * p1 + (-p0 + p2) * t + (2f * p0 - 5f * p1 + 4f * p2 - p3) * t2 + (-p0 + 3f * p1 - 3f * p2 + p3) * t3));
            }
        }
        pts.Add(ctrl[ctrl.Length - 1]);
        return pts.ToArray();
    }

    // a JSR-style rail: a bright pipe along a curve that grabs you from a couple of metres away and
    // rushes you along it until you jump off
    static SkateRail CurvyRail(string name, Vector3[] ctrl, Color32 col, bool posts = true)
    {
        var pts = Spline(ctrl, 10);
        Rail(name, pts, false);
        var rails = featureRoot.GetComponentsInChildren<SkateRail>();
        var rail = rails[rails.Length - 1];
        rail.catchRadius = CurvyCatch;
        rail.forceSpeed = CurvySpeed;
        AK("white", "e").Tube(pts, 0.09f, 6, 2f, col);
        if (posts)
        {
            float acc = 0f;
            Physics.SyncTransforms();
            for (int i = 1; i < pts.Length; i++)
            {
                acc += Vector3.Distance(pts[i - 1], pts[i]);
                if (acc < 8f) continue;
                acc = 0f;
                RaycastHit h;
                float floor = Physics.Raycast(pts[i] + Vector3.down * 0.3f, Vector3.down, out h, 80f) ? h.point.y : 0f;
                if (pts[i].y - floor > 0.6f && pts[i].y - floor < 40f) AK("metal").Cylinder(pts[i] + Vector3.down * 0.1f, new Vector3(pts[i].x, floor, pts[i].z), 0.05f, 4, 2f, new Color32(120, 120, 140, 255));
            }
        }
        return rail;
    }

    // a flying car going round a loop through the air on its own (ride on its roof)
    static GameObject FlyingCar(string name, Vector3[] path, float speed, float startAt, Color32 body)
    {
        var go = new GameObject(name, typeof(Rigidbody), typeof(Mover), typeof(BoxCollider));
        go.transform.SetParent(akRoot, false);
        go.GetComponent<Rigidbody>().isKinematic = true;
        var mesh = HoverMesh(name, body, false);
        go.AddComponent<MeshFilter>().sharedMesh = mesh;
        go.AddComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", "e"), outlineMat };
        var bc = go.GetComponent<BoxCollider>();
        bc.center = new Vector3(0f, 0.95f, 0f); bc.size = new Vector3(2.4f, 1.3f, 4.6f);
        var m = go.GetComponent<Mover>();
        m.path = path; m.loop = true; m.speed = speed; m.startAt = startAt;
        return go;
    }

    static Mesh HoverMesh(string name, Color32 body, bool ramp)
    {
        var k = new SkateMeshKit();
        k.Box(new Vector3(0f, 0.7f, 0f), new Vector3(2.4f, 0.8f, 4.6f), Quaternion.identity, body);
        k.Box(new Vector3(0f, 1.35f, 0.4f), new Vector3(2.2f, 0.5f, 2.2f), Quaternion.identity, new Color32(80, 200, 255, 255));
        k.Box(new Vector3(0f, 1.62f, 0.4f), new Vector3(2.2f, 0.06f, 2.2f), Quaternion.identity, body);
        foreach (var sx in new[] { -1.3f, 1.3f })
            foreach (var sz in new[] { -1.6f, 1.6f })
                k.Cylinder(new Vector3(sx, 0.3f, sz), new Vector3(sx, 0.36f, sz), 0.55f, 10, new Color32(255, 80, 200, 255));
        if (ramp)
        {
            // a ramp off the back, down to the ground
            Vector3 a = new Vector3(-1.1f, -0.35f, -5.4f), b = new Vector3(1.1f, -0.35f, -5.4f), c = new Vector3(1.1f, 1.1f, -2.3f), d = new Vector3(-1.1f, 1.1f, -2.3f);
            k.Quad(a, d, c, b, Vector3.up + Vector3.back, new Color32(255, 214, 40, 255));
            k.Quad(a + Vector3.down * 0.1f, b + Vector3.down * 0.1f, c + Vector3.down * 0.1f, d + Vector3.down * 0.1f, Vector3.down, new Color32(100, 100, 120, 255));
        }
        var mesh = k.Build(name);
        SaveFeatureMesh(mesh);
        return mesh;
    }

    static void AkRoute()
    {
        Hump("Route kicker", new Vector3(15.2f, Kerb, -424f), Vector3.forward, 4f, 26f, 3.6f, RampSide2);
        float porchY = 11f, pz0 = EaLot.yMin + 4f, pz1 = pz0 + 12f;
        CurvyRail("Route rail", new[] { new Vector3(15.2f, 1.4f, -417f), new Vector3(15.1f, 2.6f, -410f), new Vector3(15f, 4f, -404f), new Vector3(16.5f, 6.5f, -394f),
                                         new Vector3(17.5f, 9f, -386f), new Vector3(18.4f, porchY + 0.6f, pz0 - 2f), new Vector3(18.6f, porchY + 0.6f, pz0 + 2f) },
                  new Color32(255, 214, 40, 255));
        Vector3 pc = new Vector3(Front - 1.5f, porchY - 0.15f, (pz0 + pz1) / 2f);
        AK("concrete").Box(pc, new Vector3(3f, 0.3f, pz1 - pz0), Quaternion.identity, 3f, 3f, null, true, true);
        AkBox(pc, new Vector3(3f, 0.3f, pz1 - pz0));
        Rail("Balcony rail", new[] { new Vector3(Front - 2.9f, porchY + 1f, pz0 + 3f), new Vector3(Front - 2.9f, porchY + 1f, pz1 - 0.3f) });
        TowerCheckpoint(akRoot, new Vector3(Front - 0.6f, porchY, pz0 + 6f), "Balcony");
        float rz0 = pz1, rz1 = EaLot.yMax - 3f, rise = EaH - porchY;
        float len = Mathf.Sqrt((rz1 - rz0) * (rz1 - rz0) + rise * rise), ang = Mathf.Atan2(rise, rz1 - rz0) * Mathf.Rad2Deg;
        Vector3 rc = new Vector3(Front - 1.5f, (porchY + EaH) / 2f - 0.15f, (rz0 + rz1) / 2f);
        Quaternion rq = Quaternion.Euler(-ang, 0f, 0f);
        AK("billboard_" + AI(0, 10), "e").Box(rc, new Vector3(3f, 0.3f, len), rq, 3f, len, null, true, true);
        AkBox(rc, new Vector3(3f, 0.3f, len), rq);
        AK("concrete").Box(new Vector3(Front - 1.5f, EaH - 0.15f, (rz1 + EaLot.yMax) / 2f + 0.5f), new Vector3(3f, 0.3f, EaLot.yMax - rz1 + 1f), Quaternion.identity, 3f, 3f);
        AkBox(new Vector3(Front - 1.5f, EaH - 0.15f, (rz1 + EaLot.yMax) / 2f + 0.5f), new Vector3(3f, 0.3f, EaLot.yMax - rz1 + 1f));
        TowerCheckpoint(akRoot, new Vector3(EaLot.xMin + 6f, EaH, EaLot.yMax - 8f), "Rooftop");
        float carY = EaH - 1.85f;
        var route = new[] {
            new Vector3(16.5f, carY, -392f), new Vector3(16.5f, carY, -336f), new Vector3(4f, carY + 4f, -318f),
            new Vector3(W1Lot.xMax + 2.6f, 28f, -300f), new Vector3(W1Lot.xMax + 2.6f, 40f, -214f), new Vector3(-4f, 42f, -196f),
            new Vector3(9f, 34f, -232f), new Vector3(14f, 26f, -300f), new Vector3(16.5f, carY, -360f) };
        FlyingCar("Flying car", route, 7f, 0f, new Color32(255, 230, 60, 255));
    }

    // ---- curvy rails everywhere: long, easy to catch, and they rush you along -------------------------

    static void AkCurvyRails()
    {
        Color32[] cols = { new Color32(255, 214, 40, 255), new Color32(255, 70, 160, 255), new Color32(60, 230, 255, 255), new Color32(140, 255, 120, 255), new Color32(255, 120, 40, 255) };
        int made = 0;
        // from pavement humps up to balconies, and on up the building to its roof
        foreach (var a in akAnchors.ToArray())
        {
            if (made > 50) break;
            if (a.y < 6f || a.y > 36f || Mathf.Abs(Mathf.Abs(a.x) - (Front - 1.4f)) > 0.2f) continue;
            if (ark.NextDouble() < 0.3) continue;
            float s = Mathf.Sign(a.x), dir = ark.NextDouble() < 0.5 ? 1f : -1f;
            float kz = a.z - dir * AR(40f, 60f);
            if (Mathf.Abs(kz) > AveLen - 10f || Mathf.Abs(kz) < RailHalf + 6f) continue;
            if (s > 0f && kz > -450f && kz < -330f) continue;   // the route's stretch of pavement
            bool clear = true;
            foreach (var cz in CrossZ) if (Mathf.Abs(kz - cz) < CrossHalf + 6f || Mathf.Abs(a.z - cz) < CrossHalf + 4f) clear = false;
            if (!clear) continue;
            float px = s * (Road + 3.2f);
            akNoStall.Add(new Vector3(s, kz - 6f, kz + 6f));
            if (Reserved(kz, 8f)) continue;
            Hump("Kicker", new Vector3(px, Kerb, kz), new Vector3(0f, 0f, dir), 4f, 26f, 3.6f, RampSide2);
            BoostArrow(new Vector3(px, Kerb, kz - dir * 12f), new Vector3(0f, 0f, dir), 24f);
            var c = cols[made % cols.Length];
            CurvyRail("Curvy rail", new[] { new Vector3(px, 2.2f, kz + dir * 10f), new Vector3(px + s * AR(-1f, 1f), AR(3.5f, 6f), kz + dir * 20f),
                                             new Vector3(px - s * AR(0f, 4f), a.y * 0.5f + 2f, (kz + a.z) / 2f + dir * 6f),
                                             new Vector3(s * (Front - 3.5f), a.y * 0.8f, a.z - dir * 9f), new Vector3(s * (Front - 2.6f), a.y + 0.6f, a.z - dir * 2f),
                                             new Vector3(s * (Front - 2.6f), a.y + 0.6f, a.z) }, c);
            made++;
        }
        // across the street between balconies and roofs: big S-curves over the traffic
        var tops = akAnchors.FindAll(p => p.y > 8f && p.y < 60f && Mathf.Abs(Mathf.Abs(p.x) - Front) < 3f);
        for (int i = 0; i < 26 && tops.Count > 1; i++)
        {
            var a = tops[AI(0, tops.Count)];
            var b = tops.Find(p => Mathf.Sign(p.x) != Mathf.Sign(a.x) && Mathf.Abs(p.z - a.z) > 30f && Mathf.Abs(p.z - a.z) < 110f && Mathf.Abs(p.y - a.y) < 24f);
            if (b == Vector3.zero) continue;
            float mid = Mathf.Max(a.y, b.y) + AR(2f, 10f);
            Vector3 aa = a + new Vector3(-Mathf.Sign(a.x) * 2.6f, 0.6f, 0f), bb = b + new Vector3(-Mathf.Sign(b.x) * 2.6f, 0.6f, 0f);
            CurvyRail("Street rail", new[] { aa, Vector3.Lerp(aa, bb, 0.25f) + new Vector3(AR(-4f, 4f), AR(3f, 8f), AR(-8f, 8f)), new Vector3(AR(-6f, 6f), mid, (a.z + b.z) / 2f),
                                              Vector3.Lerp(aa, bb, 0.75f) + new Vector3(AR(-4f, 4f), AR(2f, 6f), AR(-8f, 8f)), bb }, cols[i % cols.Length], false);
        }
        // spirals round the railway pillars by the street, from the pavement up to the tracks
        foreach (var sx in new[] { -1f, 1f })
        {
            var ctrl = new List<Vector3>();
            Vector3 c0 = new Vector3(sx * (Road + 0.8f), 0f, 0f);
            for (int k = 0; k <= 12; k++)
            {
                float a = k * 50f * Mathf.Deg2Rad;
                ctrl.Add(c0 + new Vector3(Mathf.Cos(a) * 4.2f, 1.6f + k * 0.9f, Mathf.Sin(a) * 4.2f + (k < 2 ? -6f + k * 3f : 0f)));
            }
            CurvyRail("Spiral rail", ctrl.ToArray(), new Color32(255, 70, 160, 255), false);
        }
        // and long spirals up the skyscrapers, from a hump on the pavement right up to the roof
        foreach (var (lot, h) in akSkyscrapers)
        {
            if (lot == W1Lot) continue;   // that one you climb on the flying car
            float r = Mathf.Max(lot.width, lot.height) * 0.5f + 4f;
            Vector3 c = new Vector3(lot.center.x, 0f, lot.center.y);
            var ctrl = new List<Vector3>();
            float turns = Mathf.Max(2f, h / 45f);
            int n = Mathf.CeilToInt(turns * 8f);
            float a0 = Mathf.Atan2(0f, Mathf.Sign(-c.x)), streetSide = -Mathf.Sign(c.x);
            for (int k = 0; k <= n; k++)
            {
                float a = a0 + k * Mathf.PI * 2f * turns / n;
                Vector3 p = c + new Vector3(Mathf.Cos(a) * r, Mathf.Lerp(2.6f, h + 1.2f, k / (float)n), Mathf.Sin(a) * r);
                // keep it in front of the building over the pavement, not in the street
                if (Mathf.Abs(p.x) < Road + 3f) p.x = Mathf.Sign(c.x) * (Road + 3f);
                ctrl.Add(p);
            }
            ctrl.Add(new Vector3(c.x, h + 1.2f, c.z));
            Hump("Kicker", new Vector3(streetSide * -1f * (Road + 3.2f), Kerb, lot.yMin - 18f), Vector3.forward, 4f, 26f, 3.6f, RampSide2);
            ctrl.Insert(0, new Vector3(Mathf.Sign(c.x) * (Road + 3.2f), 2.2f, lot.yMin - 8f));
            CurvyRail("Skyscraper spiral", ctrl.ToArray(), cols[AI(0, cols.Length)], false);
        }
    }

    // ---- the power lines over the top of the map, between pylons on the skyscrapers ---------------

    static Vector3 PylonTop(Rect lot, float h) { return new Vector3(lot.center.x, h + 9f, lot.center.y); }

    static void Pylon(Rect lot, float h)
    {
        Vector3 b = new Vector3(lot.center.x, h, lot.center.y);
        var k = AK("metal");
        for (int i = 0; i < 4; i++)
        {
            float a = (i * 90f + 45f) * Mathf.Deg2Rad;
            k.Cylinder(b + new Vector3(Mathf.Cos(a) * 3f, 0f, Mathf.Sin(a) * 3f), b + new Vector3(Mathf.Cos(a) * 0.6f, 9f, Mathf.Sin(a) * 0.6f), 0.15f, 4, 3f, new Color32(190, 190, 205, 255));
        }
        for (float y = 2f; y < 9f; y += 2.3f) k.Box(b + Vector3.up * y, new Vector3(5f - y * 0.45f, 0.15f, 5f - y * 0.45f), Quaternion.identity, 1f, 1f);
        var bl = new GameObject("Pylon light", typeof(Blinker));
        bl.transform.SetParent(akRoot, false);
        bl.GetComponent<Blinker>().durations = new[] { 0.6f, 0.9f };
        foreach (var col in new[] { new Color32(255, 40, 40, 255), new Color32(60, 10, 10, 255) })
        {
            var lk = new SkateMeshKit();
            lk.Ellipsoid(b + Vector3.up * 9.6f, Vector3.one * 0.5f, Quaternion.identity, 8, 5, col);
            var mesh = lk.Build("Light");
            SaveFeatureMesh(mesh);
            var go = new GameObject("Lamp", typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(bl.transform, false);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterial = AkMat("white", "e");
        }
    }

    static void AkTopLines()
    {
        var lots = new[] { (E2Lot, E2H), (W3Lot, W3H), (E4Lot, E4H), (W5Lot, W5H), (E6Lot, E6H) };
        foreach (var l in lots) Pylon(l.Item1, l.Item2);
        // one long line: up the corner of the first skyscraper (a pipe on its face, easy to catch from the
        // flying car going up beside it), on up to its roof and the first pylon, then pylon to pylon
        var line = new List<Vector3>();
        float wx = W1Lot.xMax + 0.45f;
        line.AddRange(Spline(new[] { new Vector3(wx, 34f, -270f), new Vector3(wx, 38f, -240f), new Vector3(wx, 44f, -214f),
                                     new Vector3(wx, 60f, -204f), new Vector3(wx - 3f, W1H + 2f, -198f), new Vector3(wx - 10f, W1H + 4f, -194f) }, 8));
        Vector3 prev = line[line.Count - 1];
        foreach (var l in lots)
        {
            Vector3 top = PylonTop(l.Item1, l.Item2);
            var seg = Catenary(prev, top, Vector3.Distance(prev, top) * 0.03f, 18);
            for (int i = 1; i < seg.Length; i++) line.Add(seg[i]);
            prev = top;
        }
        var down = Catenary(prev, new Vector3(-30f, 31f, 445f), 3f, 14);
        for (int i = 1; i < down.Length; i++) line.Add(down[i]);
        Rail("Top line", line.ToArray(), false);
        var rails = featureRoot.GetComponentsInChildren<SkateRail>();
        rails[rails.Length - 1].catchRadius = CurvyCatch;
        rails[rails.Length - 1].forceSpeed = CurvySpeed;
        AK("white", "e").Tube(line, 0.1f, 6, 4f, new Color32(255, 214, 40, 255));
        AkTower(Rect.MinMaxRect(-50f, 420f, -16f, 470f), 30f, 1f, false);
        foreach (var l in lots)
        {
            Vector3 top = PylonTop(l.Item1, l.Item2);
            Vector3 to = new Vector3(-Mathf.Sign(top.x) * (Front + 8f), Mathf.Max(20f, top.y - 90f), top.z + 50f);
            var d2 = Catenary(top + Vector3.down * 1.5f, to, 2f, 18);
            Rail("Down line", d2, false);
            AK("white", "e").Tube(d2, 0.07f, 5, 4f, new Color32(60, 230, 255, 255));
        }
        TowerCheckpoint(akRoot, new Vector3(-33f, 30f, 450f), "End of the line");
    }

    // ---- traffic: slow, long, some you can ride up ------------------------------------------------------

    static GameObject RampTruck(string name, Color32 body)
    {
        // a flatbed with a ramp off the back: ride up the ramp onto the bed, then the cab roof
        var go = new GameObject(name, typeof(Rigidbody), typeof(Mover), typeof(MeshCollider), typeof(MeshFilter), typeof(MeshRenderer));
        go.transform.SetParent(akRoot, false);
        go.GetComponent<Rigidbody>().isKinematic = true;
        var k = new SkateMeshKit();
        float len = 14f;
        k.Box(new Vector3(0f, 1.1f, -1f), new Vector3(2.5f, 0.3f, len - 4f), Quaternion.identity, new Color32(160, 160, 175, 255));   // bed
        k.Box(new Vector3(0f, 1.7f, len / 2f - 1.5f), new Vector3(2.5f, 2.4f, 3f), Quaternion.identity, body);                       // cab
        k.Box(new Vector3(0f, 2.4f, len / 2f - 1.0f), new Vector3(2.3f, 0.8f, 1.6f), Quaternion.identity, new Color32(120, 200, 255, 255));
        Vector3 ra = new Vector3(-1.2f, 0.02f, -len / 2f - 3.5f), rb = new Vector3(1.2f, 0.02f, -len / 2f - 3.5f), rc = new Vector3(1.2f, 1.25f, -len / 2f + 1f), rd = new Vector3(-1.2f, 1.25f, -len / 2f + 1f);
        k.Quad(ra, rd, rc, rb, Vector3.up + Vector3.back, new Color32(255, 200, 40, 255));
        foreach (var sx in new[] { -1f, 1f })
            foreach (var sz in new[] { -4.5f, -1f, 5f })
                k.Cylinder(new Vector3(sx * 1.3f, 0.45f, sz), new Vector3(sx * 1.45f, 0.45f, sz), 0.45f, 10, new Color32(40, 40, 50, 255));
        var mesh = k.Build(name);
        SaveFeatureMesh(mesh);
        go.GetComponent<MeshFilter>().sharedMesh = mesh;
        go.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
        // collision: a simpler shape (bed, cab, ramp)
        var ck = new SkateMeshKit();
        ck.Box(new Vector3(0f, 0.8f, -1f), new Vector3(2.5f, 0.9f, len - 4f), Quaternion.identity, Color.white);
        ck.Box(new Vector3(0f, 1.7f, len / 2f - 1.5f), new Vector3(2.5f, 2.8f, 3f), Quaternion.identity, Color.white);
        ck.Quad(ra, rd, rc, rb, Vector3.up + Vector3.back, Color.white);
        ck.Quad(ra + Vector3.down * 0.05f, rb + Vector3.down * 0.05f, rc + Vector3.down * 0.3f, rd + Vector3.down * 0.3f, Vector3.down, Color.white);
        var cm = ck.Build(name + " collider");
        SaveFeatureMesh(cm);
        go.GetComponent<MeshCollider>().sharedMesh = cm;
        return go;
    }

    static void AkTraffic()
    {
        Color32[] cols = { new Color32(255, 255, 255, 255), new Color32(40, 40, 50, 255), new Color32(255, 214, 40, 255), new Color32(220, 40, 60, 255),
                           new Color32(60, 120, 220, 255), new Color32(200, 200, 210, 255), new Color32(120, 220, 160, 255) };
        foreach (var lane in new[] { LaneIn, LaneOut })
        {
            var path = new[] { new Vector3(-lane, 0f, -AveLen + 16f), new Vector3(-lane, 0f, AveLen - 16f), new Vector3(lane, 0f, AveLen - 16f), new Vector3(lane, 0f, -AveLen + 16f) };
            float loop = (AveLen - 16f) * 4f + lane * 4f;
            int n = lane < 7f ? 12 : 10;
            for (int i = 0; i < n; i++)
            {
                GameObject v;
                bool bus = lane > 7f && i % 3 == 0, ramp = lane < 7f && i % 3 == 1;
                if (ramp) v = RampTruck("Ramp truck", cols[i % cols.Length]);
                else
                {
                    v = Vehicle(akRoot, bus ? "Bus" : "Car", bus ? 16f : AR(4.4f, 5.4f), bus ? 2.6f : 1.9f, bus ? 2.9f : 1.6f, bus ? new Color32(250, 250, 255, 255) : cols[i % cols.Length], new Color32(60, 180, 80, 255), bus);
                    v.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
                    // photo sides on the buses
                    if (bus)
                    {
                        var side = new GameObject("Bus sides", typeof(MeshFilter), typeof(MeshRenderer));
                        side.transform.SetParent(v.transform, false);
                        var sk = new PSXKit();
                        foreach (var sx in new[] { -1f, 1f })
                            sk.Panel(new Vector3(sx * 1.32f, 1.85f, 0f), Rt(new Vector3(sx, 0f, 0f)) * 8f, Vector3.up * 1.45f);
                        var sm = sk.Build("Bus sides");
                        SaveFeatureMesh(sm);
                        side.GetComponent<MeshFilter>().sharedMesh = sm;
                        side.GetComponent<MeshRenderer>().sharedMaterial = AkMat("photo_bus", "");
                    }
                }
                var m = v.GetComponent<Mover>();
                m.path = path; m.loop = true; m.speed = bus ? 3.5f : ramp ? 3.5f : 5f; m.startAt = loop * i / n;
                if (lane > 7f) m.speed = 3.5f;   // the outer lanes all go at the buses' pace, so nothing runs into them
            }
        }
        // flying cars looping over the street on their own (ride on their roofs)
        FlyingCar("Flying car", new[] { new Vector3(-6f, 18f, -150f), new Vector3(6f, 26f, -40f), new Vector3(-6f, 34f, 90f), new Vector3(6f, 26f, 220f), new Vector3(0f, 20f, 90f), new Vector3(0f, 16f, -60f) }, 8f, 0f, new Color32(255, 80, 200, 255));
        FlyingCar("Flying car", new[] { new Vector3(10f, 40f, 120f), new Vector3(-10f, 60f, 260f), new Vector3(10f, 80f, 400f), new Vector3(-6f, 60f, 300f), new Vector3(6f, 40f, 180f) }, 8f, 40f, new Color32(60, 230, 255, 255));
        FlyingCar("Flying car", new[] { new Vector3(-4f, 12f, -440f), new Vector3(4f, 22f, -330f), new Vector3(-4f, 30f, -220f), new Vector3(4f, 16f, -330f) }, 7f, 0f, new Color32(140, 255, 120, 255));
    }

    // ---- flying cars you fly yourself: ride up the ramp on the back --------------------------------------

    static void AkHoverCars()
    {
        var spots = new List<(Vector3, float)> {
            (new Vector3(0f, 0.35f, -446f), 0f), (new Vector3(0f, 0.35f, -60f), 0f), (new Vector3(0f, 0.35f, 120f), 180f), (new Vector3(0f, 0.35f, 400f), 180f),
            (new Vector3(60f, 0.35f, -160f), 90f), (new Vector3(-80f, 0.35f, 160f), -90f), (new Vector3(100f, 0.35f, 320f), 90f) };
        // and a couple on roofs, to fly up higher from
        spots.Add((new Vector3(EaLot.center.x + 4f, EaH + 0.35f, EaLot.center.y), 90f));
        // and on mid-height rooftops, pointing along the street over the other roofs
        int roofCars = 0;
        foreach (var (lot, h, _) in akLots)
        {
            if (h < 40f || h > 115f || lot.height < 14f || roofCars >= 6) continue;
            if (roofCars > 0 && ark.NextDouble() < 0.4) continue;
            spots.Add((new Vector3(lot.center.x, h + 0.35f, lot.center.y), lot.center.y < 0f ? 0f : 180f));
            roofCars++;
        }
        Color32[] cols = { new Color32(255, 230, 60, 255), new Color32(255, 80, 200, 255), new Color32(60, 230, 255, 255), new Color32(255, 140, 40, 255) };
        int i = 0;
        foreach (var (at, yaw) in spots)
        {
            var go = new GameObject("Flyable car", typeof(Rigidbody), typeof(HoverCar), typeof(MeshCollider), typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(akRoot, false);
            go.transform.SetPositionAndRotation(at, Quaternion.Euler(0f, yaw, 0f));
            go.GetComponent<Rigidbody>().isKinematic = true;
            var mesh = HoverMesh("Flyable car", cols[i++ % cols.Length], true);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", "e"), outlineMat };
            go.GetComponent<MeshCollider>().sharedMesh = mesh;
            var hc = go.GetComponent<HoverCar>();
            hc.climb = 60f; hc.speed = 38f; hc.fuse = 4f;
            hc.seat = new Vector3(0f, 1.7f, -0.8f);
            hc.fire = Burst(go.transform, "Explosion", new Color(1f, 0.55f, 0.1f), new Color(1f, 0.95f, 0.4f), 1.2f, 3.5f, 14f, 26f, 0.7f, 120);
            hc.smoke = Burst(go.transform, "Smoke", new Color(0.25f, 0.2f, 0.3f, 0.8f), new Color(0.5f, 0.45f, 0.55f, 0.6f), 2.5f, 5f, 3f, 8f, 2.2f, 40);
        }
    }

    // a one-shot burst of particles (an explosion's fireball or smoke), played from code
    static ParticleSystem Burst(Transform parent, string name, Color a, Color b, float size0, float size1, float speed0, float speed1, float life, int count)
    {
        var go = new GameObject(name, typeof(ParticleSystem));
        go.transform.SetParent(parent, false);
        go.transform.localPosition = Vector3.up;
        var ps = go.GetComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = false; main.playOnAwake = false; main.duration = 0.5f;
        main.startLifetime = new ParticleSystem.MinMaxCurve(life * 0.6f, life);
        main.startSpeed = new ParticleSystem.MinMaxCurve(speed0, speed1);
        main.startSize = new ParticleSystem.MinMaxCurve(size0, size1);
        main.startColor = new ParticleSystem.MinMaxGradient(a, b);
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.gravityModifier = -0.2f;
        main.maxParticles = count * 2;
        var em = ps.emission; em.rateOverTime = 0f;
        em.SetBursts(new[] { new ParticleSystem.Burst(0f, (short)count) });
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Sphere; shape.radius = 1f;
        var fade = ps.colorOverLifetime; fade.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(new Color(0.5f, 0.4f, 0.4f), 1f) },
                     new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0f, 1f) });
        fade.color = grad;
        var grow = ps.sizeOverLifetime; grow.enabled = true; grow.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0.6f, 1f, 1.6f));
        go.GetComponent<ParticleSystemRenderer>().sharedMaterial = Mat("Sparks", "Sprites/Default");
        return ps;
    }

    // ---- weird stuff: lucky cats, hologram signs, a blimp ------------------------------------------------

    static void AkWeird()
    {
        foreach (var at in new[] { new Vector3(34f, 0f, -250f), new Vector3(-36f, 0f, 200f), new Vector3(38f, 0f, 380f), new Vector3(-40f, 0f, -420f) })
        {
            RaycastHit h;
            Physics.SyncTransforms();
            float y = Physics.Raycast(at + Vector3.up * 300f, Vector3.down, out h, 400f) ? h.point.y : 0f;
            var k = new SkateMeshKit();
            Vector3 c = new Vector3(at.x, y, at.z);
            Color32 white = new Color32(250, 250, 250, 255), red = new Color32(230, 40, 50, 255), gold = new Color32(255, 210, 60, 255);
            k.Ellipsoid(c + Vector3.up * 2.4f, new Vector3(2.2f, 2.4f, 2f), Quaternion.identity, 14, 10, white);
            k.Ellipsoid(c + Vector3.up * 5.4f, new Vector3(1.8f, 1.6f, 1.6f), Quaternion.identity, 14, 10, white);
            foreach (var sx in new[] { -1f, 1f }) k.Cone(c + new Vector3(sx * 1.1f, 6.6f, 0f), 0.6f, 0f, 1.2f, 6, white, 0f);
            k.Ellipsoid(c + new Vector3(1.6f, 6.4f, -0.4f), new Vector3(0.5f, 1.2f, 0.5f), Quaternion.Euler(0f, 0f, -15f), 8, 6, white);
            k.Box(c + new Vector3(0f, 4.2f, -1.7f), new Vector3(2.4f, 0.4f, 0.3f), Quaternion.identity, red);
            k.Ellipsoid(c + new Vector3(0f, 3.6f, -1.9f), new Vector3(0.5f, 0.5f, 0.2f), Quaternion.identity, 8, 6, gold);
            foreach (var sx in new[] { -0.6f, 0.6f }) k.Ellipsoid(c + new Vector3(sx, 5.6f, -1.5f), new Vector3(0.25f, 0.12f, 0.1f), Quaternion.identity, 6, 4, new Color32(30, 30, 30, 255));
            var mesh = k.Build("Lucky cat");
            SaveFeatureMesh(mesh);
            MeshObject("Lucky cat", akRoot, mesh, AkMat("white", ""), outlineMat);
            var col = new GameObject("Cat").AddComponent<CapsuleCollider>();
            col.transform.SetParent(akCol, false); col.transform.position = c + Vector3.up * 3.5f; col.radius = 2.1f; col.height = 7f;
        }
        for (int i = 0; i < 12; i++)
        {
            var go = new GameObject("Hologram", typeof(MeshFilter), typeof(MeshRenderer), typeof(Spin));
            go.transform.SetParent(akRoot, false);
            var k = new PSXKit();
            k.Panel(Vector3.zero, Vector3.right * 3.5f, Vector3.up * 3.5f, null, true);
            var mesh = k.Build("Hologram");
            SaveFeatureMesh(mesh);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterial = AkMat("billboard_" + AI(0, 10), "f");
            go.transform.position = new Vector3(AR(-6f, 6f), AR(16f, 60f), -AveLen + 50f + i * 75f);
            var sp = go.GetComponent<Spin>(); sp.degreesPerSecond = AR(20f, 50f); sp.bob = 1f;
        }
        var blimp = new GameObject("Blimp", typeof(Rigidbody), typeof(Mover));
        blimp.transform.SetParent(akRoot, false);
        blimp.GetComponent<Rigidbody>().isKinematic = true;
        var bk = new SkateMeshKit();
        bk.Ellipsoid(Vector3.zero, new Vector3(7f, 7f, 22f), Quaternion.identity, 16, 10, new Color32(240, 240, 250, 255));
        bk.Box(new Vector3(0f, -7.5f, 0f), new Vector3(2.5f, 2f, 6f), Quaternion.identity, new Color32(80, 80, 100, 255));
        foreach (var f in new[] { Quaternion.identity, Quaternion.Euler(0f, 0f, 90f) })
            bk.Box(new Vector3(0f, 0f, -19f), f * new Vector3(0.3f, 9f, 5f), f, new Color32(255, 70, 160, 255));
        var bm = bk.Build("Blimp");
        SaveFeatureMesh(bm);
        blimp.AddComponent<MeshFilter>().sharedMesh = bm;
        blimp.AddComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
        var ledk = new PSXKit();
        foreach (var s in new[] { -1f, 1f }) ledk.Panel(new Vector3(s * 7.15f, 0f, 0f), Rt(new Vector3(s, 0f, 0f)) * 14f, Vector3.up * 1.5f, null, false, new Rect(0f, 0f, 4.4f, 1f));
        var lm = ledk.Build("Blimp sign");
        SaveFeatureMesh(lm);
        var sign = new GameObject("Blimp sign", typeof(MeshFilter), typeof(MeshRenderer));
        sign.transform.SetParent(blimp.transform, false);
        sign.GetComponent<MeshFilter>().sharedMesh = lm;
        sign.GetComponent<MeshRenderer>().sharedMaterial = AkMat("led_0", "s");
        var bmv = blimp.GetComponent<Mover>();
        var bp = new List<Vector3>();
        for (int i = 0; i < 16; i++) { float a = i * Mathf.PI * 2f / 16; bp.Add(new Vector3(Mathf.Cos(a) * 160f, 250f, Mathf.Sin(a) * 400f)); }
        bmv.path = bp.ToArray(); bmv.loop = true; bmv.speed = 9f;
    }

